L["Blizzard's health and cast bar art, or the classic flat plates, with every EllesmereUI nameplate feature."] = "El arte de barras de vida y lanzamiento de Blizzard, o las placas planas clásicas, con todas las funciones de placas de nombre de EllesmereUI."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI meter feature."] = "El arte de ventana y barras del medidor de Blizzard, o una ventana con el borde clásico de las pestañas de chat, con todas las funciones del medidor de EllesmereUI."
L["Blizzard's meter window and bar art, or a window in the classic chat tabs' border, with every EllesmereUI threat meter feature."] = "El arte de ventana y barras del medidor de Blizzard, o una ventana con el borde clásico de las pestañas de chat, con todas las funciones del medidor de amenaza de EllesmereUI."
L["Blizzard's own character sheet as the game draws it; WoW Forever keeps the item text beside the slots, and the stat colors stay with the EllesmereUI look."] = "La hoja de personaje propia de Blizzard tal como la dibuja el juego; WoW Forever mantiene el texto de objetos junto a las casillas y los colores de estadísticas siguen el estilo de EllesmereUI."
L["Blizzard's own character sheet with the EllesmereUI stats, slot text and socket panel added; the Calc tab stays with the EllesmereUI look."] = "La hoja de personaje propia de Blizzard con las estadísticas, el texto de casillas y el panel de ranuras de EllesmereUI añadidos; la pestaña Calc mantiene el estilo de EllesmereUI."
L["Blizzard's own chat window, tabs and input box, or the same window with the classic tab art, with every EllesmereUI chat feature."] = "La ventana de chat, pestañas y campo de entrada propios de Blizzard, o la misma ventana con el arte clásico de pestañas, con todas las funciones de chat de EllesmereUI."
L["Blizzard's own frame and button art, with EllesmereUI's features."] = "El arte propio de marcos y botones de Blizzard, con las funciones de EllesmereUI."
L["Blizzard's own friends window and cards, with the EllesmereUI class icons, class-coloured names and region icons added. Both stock styles look the same here."] = "La ventana y tarjetas de amigos propias de Blizzard, con los iconos de clase, nombres con color de clase e iconos de región de EllesmereUI añadidos. Ambos estilos originales se ven igual aquí."
L["Blizzard's own tracker, with every EllesmereUI tracker feature. Both stock styles look the same here."] = "El seguimiento propio de Blizzard, con todas las funciones de seguimiento de EllesmereUI. Ambos estilos originales se ven igual aquí."
L["Blizzard's raid frame edge and highlights, or the classic ones, with every EllesmereUI raid frame feature."] = "El borde y los resaltados de marcos de banda de Blizzard, o los clásicos, con todas las funciones de marcos de banda de EllesmereUI."
L["Blizzard's round minimap and header, or the classic ring, with every EllesmereUI minimap feature."] = "El minimapa redondo y su encabezado de Blizzard, o el anillo clásico, con todas las funciones de minimapa de EllesmereUI."
L["Blizzard's rounded button art, or the classic square slots, with every EllesmereUI bar feature."] = "El arte de botones redondeados de Blizzard, o las casillas cuadradas clásicas, con todas las funciones de barra de EllesmereUI."
L["Blizzard's rounded cooldown icons, or the classic square slots, with every EllesmereUI icon feature."] = "Los iconos de reutilización redondeados de Blizzard, o las casillas cuadradas clásicas, con todas las funciones de iconos de EllesmereUI."
L["Blizzard's windows now match the EllesmereUI theme with a WoW 2.0 Dark Theme, from the Dungeon Journal to the Auction House and beyond."] = "Las ventanas de Blizzard ahora siguen el tema de EllesmereUI con un tema oscuro WoW 2.0, desde la guía de mazmorras hasta la casa de subastas y más allá."
