L["Color the health bar by how much health is left, instead of a flat color. Classic runs green at full health through yellow to red at empty. Custom Colors blends between the three stop swatches on this row -- full (100%), half (50%) and empty (0%). Class Reactive shows the class color at full health, bleeding into the 50% and 0% colors as the unit takes damage. Off leaves the flat Fill Color swatches in charge; either way the Gradient below still applies, running from whichever color this picks."] = "Colorea la barra de vida según la vida restante, en lugar de un color fijo. Clásico va de verde con la vida llena, pasando por amarillo, a rojo cuando está vacía. Colores personalizados mezcla las tres muestras de esta fila: llena (100%), media (50%) y vacía (0%). Reactivo de clase muestra el color de clase con la vida llena y se funde hacia los colores del 50% y 0% a medida que la unidad recibe daño. Desactivado deja al mando las muestras de Color de relleno; en ambos casos se sigue aplicando el Degradado de abajo, partiendo del color que se elija aquí."
L["COLORS"] = "COLORES"
L["Colors"] = "Colores"
L["Colors allied player bars using their class. Group/raid members are identified automatically; other allies are learned from target, mouseover or focus."] = "Colorea las barras de jugadores aliados según su clase. Los miembros del grupo o banda se identifican automáticamente; los demás aliados se aprenden del objetivo, el ratón o el foco."
L["Colors an attackable unit's level by difficulty, as the default UI does."] = "Colorea el nivel de una unidad atacable según su dificultad, como la interfaz predeterminada."
L["Colors are shared globally from the \"%1$s\" profile.\nSwitch to it (or set Pull Colors From to this profile) to edit."] = "Los colores se comparten globalmente desde el perfil \"%1$s\".\nCambia a él (o ajusta Tomar colores de a este perfil) para editarlos."
L["Colors group and raid member names inside Say, Yell, Party and Raid messages."] = "Colorea los nombres de los miembros del grupo y la banda en los mensajes de Decir, Gritar, Grupo y Banda."
L["Colors level text by difficulty, from grey (trivial) through green, yellow and orange to red (5+ levels above you)."] = "Colorea el texto de nivel según la dificultad, de gris (trivial) pasando por verde, amarillo y naranja hasta rojo (5+ niveles por encima de ti)."
L["Colors the bar text instead of the fill when the threshold applies."] = "Colorea el texto de la barra en lugar del relleno cuando se aplica el umbral."
L["Colors the cast segment during which your interrupt will be available."] = "Colorea el tramo del lanzamiento durante el que tu interrupción estará disponible."
L["Colors the dispel type borders with your Dispel Colors instead of Blizzard's."] = "Colorea los bordes por tipo de disipación con tus Colores de disipación en lugar de los de Blizzard."
L["Colors the number by threat status. Off shows it in white."] = "Colorea el número según el estado de amenaza. Desactivado lo muestra en blanco."
L["Colors the number when free slots drop below this many; the swatch picks the color. Zero turns it off."] = "Colorea el número cuando los huecos libres bajan de esta cantidad; la muestra elige el color. Cero lo desactiva."
L["Colors the strip behind the target's name by its reaction."] = "Colorea la franja detrás del nombre del objetivo según su reacción."
