L["Hide public chat ads containing whole words such as WTS, WTB, WTT, LFW, selling, buying, vendo or compro. Needs Public Chat above. Does not hide the entire Trade channel."] = "Oculta anuncios del chat público que contengan palabras completas como WTS, WTB, WTT, LFW, selling, buying, vendo o compro. Requiere Chat público arriba. No oculta todo el canal de Comercio."
L["Hide Rank Numbers"] = "Ocultar números de rango"
L["Hide repeated messages within the repeat window. Your own messages are always shown. Requires Enable Chat."] = "Oculta los mensajes repetidos dentro del intervalo de repetición. Tus propios mensajes siempre se muestran. Requiere Activar chat."
