L["Hide server death announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\". Works in every chat window, independent of the chat types above."] = "Oculta los anuncios de muerte del servidor como \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\". Funciona en todas las ventanas de chat, independientemente de los tipos de chat de arriba."
