L["Hides the Objectives header and its minimize button at the top of the tracker."] = "Oculta el encabezado de Objetivos y su botón de minimizar en la parte superior del rastreador."
L["Hides the Objectives header and its minimize button at the top of the tracker. When shown, it uses the Header Color with a divider in the Line Color."] = "Oculta el encabezado de Objetivos y su botón de minimizar en la parte superior del rastreador. Cuando se muestra, usa el Color del encabezado con un divisor en el Color de línea."
L["Hides the resize handle on the main chat frame, preventing accidental resizing."] = "Oculta el control de redimensionado del marco de chat principal, evitando cambios de tamaño accidentales."
