L["Hides the thin dividers between the messages, input field and sidebar."] = "Oculta los divisores finos entre los mensajes, el campo de texto y la barra lateral."
L["Hides the Unlock Mode button from the game's Escape/pause menu. You can still toggle Unlock Mode from the EUI options panel."] = "Oculta el botón de Modo de desbloqueo del menú de Escape/pausa del juego. Aún puedes activar el Modo de desbloqueo desde el panel de opciones de EUI."
L["Hides this element while you are on a skyriding (glide-capable) mount, where Blizzard shows its vigor HUD."] = "Oculta este elemento mientras vas en una montura de vuelo dinámico (capaz de planear), donde Blizzard muestra su HUD de vigor."
