L["Holds the block at this width and clips longer text, so a plugin whose text keeps changing length never shifts the blocks beside it. Zero sizes the block to whatever the plugin currently says."] = "Mantiene el bloque con este ancho y recorta el texto más largo, para que un plugin cuyo texto cambia de longitud nunca desplace los bloques contiguos. Cero ajusta el bloque a lo que muestre el plugin en ese momento."
