L["Include your complete override setup: spec and conditional override values, groups, their custom Unlock Mode layouts, and Buff Manager overrides. On import this replaces the recipient's overrides entirely."] = "Incluye tu configuración completa de anulaciones: valores de anulación por especialización y condicionales, grupos, sus disposiciones personalizadas del Modo desbloqueo y las anulaciones del Gestor de beneficios. Al importar, esto reemplaza por completo las anulaciones del destinatario."
L["Include your Cooldown Manager spell layout (which spells sit on which bars) plus all per-spell settings for any specs you choose."] = "Incluye la disposición de hechizos de tu Gestor de reutilización (qué hechizos van en qué barras) y todos los ajustes por hechizo de las especializaciones que elijas."
