L["Shows a small white tick mark on the cast bar at the point where the cast will be when your interrupt comes off cooldown."] = "Muestra una pequeña marca blanca en la barra de lanzamiento en el punto en que estará el lanzamiento cuando tu interrupción salga de reutilización."
L["Shows a small white tick mark where the cast will be when your interrupt comes off cooldown."] = "Muestra una pequeña marca blanca donde estará el lanzamiento cuando tu interrupción salga de reutilización."
L["Shows an envelope icon when you have unread mail."] = "Muestra un icono de sobre cuando tienes correo sin leer."
L["Shows debuffs that match any checked Show filter (the default)."] = "Muestra los perjuicios que coincidan con cualquier filtro Mostrar marcado (predeterminado)."
L["Shows every bar with placeholder icons while the options are open."] = "Muestra todas las barras con iconos de ejemplo mientras las opciones están abiertas."
L["Shows every debuff on this frame."] = "Muestra todos los perjuicios en este marco."
L["Shows incoming heals past the health bar: yours, then other players'."] = "Muestra las sanaciones entrantes más allá de la barra de vida: las tuyas y luego las de otros jugadores."
L["Shows large amounts using K/M suffixes (284,208g becomes 284.2Kg) instead of the full grouped number. The tooltip always shows the exact amount."] = "Muestra las cantidades grandes con sufijos K/M (284,208g pasa a 284.2Kg) en vez del número completo. El tooltip siempre muestra la cantidad exacta."
L["Shows only debuffs Blizzard flags as important."] = "Muestra solo los perjuicios que Blizzard marca como importantes."
L["Shows only debuffs that match every checked Show filter (dispel types count as one); opposites like Non-Player Auras with Cast By You show nothing."] = "Muestra solo los perjuicios que coincidan con todos los filtros Mostrar marcados (los tipos de disipación cuentan como uno); opuestos como Auras no de jugador con Lanzado por ti no muestran nada."
L["Shows only the debuffs you apply that Blizzard also flags as important."] = "Muestra solo los perjuicios que aplicas tú y que Blizzard también marca como importantes."
L["Shows only the debuffs you apply."] = "Muestra solo los perjuicios que aplicas tú."
L["Shows only this frame's Tracked Auras; add them with Edit Tracked Auras at the top of this menu."] = "Muestra solo las auras rastreadas de este marco; añádelas con Editar auras rastreadas en la parte superior de este menú."
L["Shows silver and copper, not just gold."] = "Muestra plata y cobre, no solo oro."
L["Shows the audio icon next to the volume bar."] = "Muestra el icono de audio junto a la barra de volumen."
L["Shows the bag icon next to the slot count."] = "Muestra el icono de bolsa junto al recuento de ranuras."
L["Shows the coin icon next to the amount."] = "Muestra el icono de moneda junto a la cantidad."
L["Shows the combat status text only while your character is in combat."] = "Muestra el texto de estado de combate solo mientras tu personaje está en combate."
L["Shows the cost of the spell being cast on the power bar."] = "Muestra en la barra de recursos el coste del hechizo que se está lanzando."
L["Shows the currency icon next to the amount."] = "Muestra el icono de la divisa junto a la cantidad."
L["Shows the currency's description text in the tooltip. Turn off for a compact tooltip with just the name and the amount."] = "Muestra el texto de descripción de la divisa en el tooltip. Desactívalo para un tooltip compacto con solo el nombre y la cantidad."
L["Shows the debuffs you apply plus important debuffs from anyone."] = "Muestra los perjuicios que aplicas tú más los perjuicios importantes de cualquiera."
L["Shows the frame while this unit is below full health; while enabled, a frame hidden by its visibility setting can still be clicked."] = "Muestra el marco mientras esta unidad no tenga la vida completa; mientras esté activado, un marco oculto por su ajuste de visibilidad aún se puede pulsar."
L["Shows the health text elements placed in Core Text Positions."] = "Muestra los elementos de texto de vida colocados en Posiciones de texto principales."
L["Shows the icon next to the durability readout."] = "Muestra el icono junto a la lectura de durabilidad."
L["Shows the last lines of each chat window again after a reload or relog."] = "Vuelve a mostrar las últimas líneas de cada ventana de chat tras recargar o volver a conectar."
L["Shows the map pin next to the zone name."] = "Muestra el marcador del mapa junto al nombre de la zona."
L["Shows the marker icon next to the coordinates."] = "Muestra el icono de marcador junto a las coordenadas."
L["Shows the most important boss debuff (ICC, Ruby Sanctum, ToC, Ulduar, Naxxramas) as a large icon in the middle of the frame."] = "Muestra el perjuicio de jefe más importante (ICC, Sagrario Rubí, ToC, Ulduar, Naxxramas) como un icono grande en el centro del marco."
L["Shows the network latency zone at the end of casts or channels, including queued spells."] = "Muestra la zona de latencia de red al final de los lanzamientos o canalizaciones, incluidos los hechizos en cola."
L["Shows the online friend and guild counters."] = "Muestra los contadores de amigos y hermandad conectados."
L["Shows the overlay only for debuffs you can currently dispel."] = "Muestra la superposición solo para los perjuicios que puedes disipar ahora."
L["Shows the plugin's own icon next to its text."] = "Muestra el icono propio del plugin junto a su texto."
L["Shows the plugin's text. Off leaves an icon-only block that still carries the plugin's tooltip and clicks."] = "Muestra el texto del plugin. Desactivado deja un bloque solo con icono que mantiene el tooltip y los clics del plugin."
L["Shows the profession icons next to the text."] = "Muestra los iconos de profesión junto al texto."
L["Shows the raid target marker icon on boss frames."] = "Muestra el icono de marca de banda en los marcos de jefe."
L["Shows the spec icon next to the text."] = "Muestra el icono de especialización junto al texto."
L["Shows the spell icon over the portrait while casting and lets the bar use the full width."] = "Muestra el icono del hechizo sobre el retrato al lanzar y deja que la barra use todo el ancho."
L["Shows the stock rune or combo point frame here instead of the pips."] = "Muestra aquí el marco original de runas o puntos de combo en vez de los indicadores."
L["Shows the unit's level in the frame's level circle, as the default UI does."] = "Muestra el nivel de la unidad en el círculo de nivel del marco, como la IU predeterminada."
L["Shows the zone and the subzone together instead of the subzone alone."] = "Muestra la zona y la subzona juntas en vez de solo la subzona."
L["Shows your arena opponents. Left click targets, right click sets focus."] = "Muestra a tus rivales de arena. Clic izquierdo para seleccionar, clic derecho para fijar foco."
L["Shows your free bag slots."] = "Muestra tus ranuras de bolsa libres."
