L["Shows your interrupt while your focus is casting."] = "Muestra tu interrupción mientras tu foco lanza."
L["Shows your interrupt while your focus or target is casting."] = "Muestra tu interrupción mientras tu foco u objetivo lanza."
L["Shows your threat percentage on the target and focus frames while you are in combat with that unit."] = "Muestra tu porcentaje de amenaza en los marcos de objetivo y foco mientras estás en combate con esa unidad."
