L["The Armory"] = "La Armería"
L["The background colour behind Dark Mode bars (Unit Frames, Raid Frames, Resource Bars)."] = "El color de fondo detrás de las barras en Modo oscuro (Marcos de unidad, Marcos de banda, Barras de recurso)."
L["The bank opens anywhere from the Bags header; away from a banker it shows the last saved contents."] = "El banco se abre desde cualquier lugar con el encabezado de Bolsas; lejos de un banquero muestra el último contenido guardado."
L["The bar shows stacks out of the maximum instead of time."] = "La barra muestra las acumulaciones sobre el máximo en lugar del tiempo."
L["The bar this page edits."] = "La barra que edita esta página."
L["The Combat Indicator is not available for the Focus frame."] = "El indicador de combate no está disponible para el marco de foco."
L["The Cooldown Manager can do far more than show cooldowns, it also has per-spell settings, bar glows, tracking bars and more! Check out some tips and tricks for getting more from it."] = "¡El Gestor de reutilización puede hacer mucho más que mostrar reutilizaciones: también tiene ajustes por hechizo, resplandores de barra, barras de seguimiento y más! Echa un vistazo a algunos trucos y consejos para sacarle más partido."
L["The display language for the EllesmereUI options panel. Auto follows your game client. Untranslated text falls back to English."] = "El idioma de visualización del panel de opciones de EllesmereUI. Auto sigue a tu cliente del juego. El texto sin traducir se muestra en inglés."
L["the EllesmereUI theme"] = "el tema de EllesmereUI"
L["The exact inverse of Skyriding (Airborne): anything that is not airborne on a glide-capable mount or flight form, standing on the ground included."] = "El inverso exacto de Surcacielos (en el aire): todo lo que no sea estar en el aire con una montura capaz de planear o en forma de vuelo, incluido estar en el suelo."
L["The fallback must differ from\nthe main anchor target"] = "El respaldo debe ser distinto\ndel objetivo de anclaje principal"
L["The flat fill colour bars use when Dark Mode is enabled (Unit Frames, Raid Frames, Resource Bars)."] = "El color de relleno plano que usan las barras con el Modo oscuro activado (Marcos de unidad, Marcos de banda, Barras de recurso)."
L["the Frame Source to be EllesmereUI"] = "que el origen del marco sea EllesmereUI"
L["The gem could not be socketed."] = "No se pudo engarzar la gema."
L["The glow line is not shown on a vertical fill or with the From Left Edge placement"] = "La línea de resplandor no se muestra con relleno vertical ni con la colocación Desde el borde izquierdo"
L["The glow line is not shown on a vertical fill or with the From Right Edge placement"] = "La línea de resplandor no se muestra con relleno vertical ni con la colocación Desde el borde derecho"
L["The glow line is not shown with Absorb Style None"] = "La línea de resplandor no se muestra con el estilo de absorción Ninguno"
L["The Lich King"] = "El Rey Exánime"
L["the Modern background style"] = "el estilo de fondo Moderno"
L["The native social window with class icons, class-coloured names, faction banners and invite auto-accept; friend actions and every social tab stay native."] = "La ventana social nativa con iconos de clase, nombres con color de clase, estandartes de facción y aceptación automática de invitaciones; las acciones de amigos y todas las pestañas sociales siguen siendo nativas."
L["The original frames, rings and slots where the game has them, with EllesmereUI's features."] = "Los marcos, anillos y ranuras originales donde el juego los tiene, con las funciones de EllesmereUI."
L["The override group '%s' already provides the custom unlock mode for your current spec. Customize it there, or remove this spec from that group."] = "El grupo de anulación '%s' ya proporciona el Modo desbloqueo personalizado para tu especialización actual. Personalízalo allí o quita esta especialización de ese grupo."
L["The pasted string could not be read completely. Please paste it again."] = "No se pudo leer por completo la cadena pegada. Vuelve a pegarla."
L["The personal resource display's bar frame, or the classic cast bar frame, on the health, power and class resource bars, with every EllesmereUI bar feature."] = "El marco de barra de la visualización de recursos personal, o el marco clásico de barra de lanzamiento, en las barras de vida, recurso y recurso de clase, con todas las funciones de barra de EllesmereUI."
L["The Pixel Glow settings this bar's per-icon glows use. The template never changes them."] = "Los ajustes de Pixel Glow que usan los resplandores por icono de esta barra. La plantilla nunca los cambia."
L["the Randomly trigger"] = "el activador Aleatorio"
L["The Ring of Valor"] = "El Anillo del Valor"
L["The scriptProfile CVar is enabled."] = "La CVar scriptProfile está activada."
L["The socketed gem will be destroyed. Continue?"] = "La gema engarzada se destruirá. ¿Continuar?"
L["The taintLog and scriptProfile CVars are enabled."] = "Las CVars taintLog y scriptProfile están activadas."
L["The taintLog CVar is enabled."] = "La CVar taintLog está activada."
L["The tracker always hides in arenas"] = "El seguimiento siempre se oculta en arenas"
L["These are the same settings found on each module's own pages, not separate ones."] = "Son los mismos ajustes que hay en las páginas de cada módulo, no ajustes distintos."
L["These settings prioritize frame rate and visual clarity over environmental detail. Textures stay high quality so your character and the world still look perfect."] = "Estos ajustes priorizan la tasa de fotogramas y la claridad visual sobre el detalle del entorno. Las texturas mantienen alta calidad para que tu personaje y el mundo sigan viéndose perfectos."
L["These specs hold override values that no group's editing mode can reach anymore (left behind by membership changes). They still apply. Remove one to return that spec to the shared default."] = "Estas especializaciones tienen valores de anulación que ya no alcanza el modo de edición de ningún grupo (quedaron por cambios de miembros). Siguen aplicándose. Quita una para devolver esa especialización al valor predeterminado compartido."
L["Thick"] = "Grueso"
L["Thickness"] = "Grosor"
L["Thickness in pixels. -1 follows each debuff indicator's Border setting, 0 hides the dispel color border."] = "Grosor en píxeles. -1 sigue el ajuste de Borde de cada indicador de perjuicio, 0 oculta el borde de color de disipación."
L["Thin Line Bottom"] = "Línea fina inferior"
L["Thin Line Top"] = "Línea fina superior"
L["This bar sizes its blocks itself, so the width is not this block's to choose."] = "Esta barra ajusta el tamaño de sus bloques por sí misma, así que el ancho no lo elige este bloque."
L["This bar will only show if you have an enemy targeted"] = "Esta barra solo se mostrará si tienes un enemigo como objetivo"
L["This block is already the 'Fill Remaining Space' block. Check another block to move the role."] = "Este bloque ya es el bloque 'Rellenar espacio restante'. Marca otro bloque para mover la función."
L["This can't change which spells the user tracks in Blizzard's CDM.\nIt's recommended to also share your Blizzard CDM layout for any spec you choose here."] = "Esto no puede cambiar qué hechizos rastrea el usuario en el CDM de Blizzard.\nSe recomienda compartir también tu diseño del CDM de Blizzard para cada especialización que elijas aquí."
L["This cannot be undone. Consider exporting this profile as a backup first."] = "Esto no se puede deshacer. Considera exportar este perfil como copia de seguridad primero."
L["This cannot be undone. Export your own profile as a backup first."] = "Esto no se puede deshacer. Exporta primero tu propio perfil como copia de seguridad."
L["This condition is coming in a future update."] = "Esta condición llegará en una futura actualización."
L["This conditional is not active right now. Meet one of its conditions first (for example, enter the dungeon) so you can arrange the layout in its real context."] = "Este condicional no está activo ahora mismo. Cumple primero una de sus condiciones (por ejemplo, entra en la mazmorra) para poder organizar el diseño en su contexto real."
L["This control recently changed direction: it now copies FROM the frame you choose. Confirming will copy all shared settings FROM %1$s TO %2$s."] = "Este control cambió de dirección recientemente: ahora copia DESDE el marco que elijas. Al confirmar se copiarán todos los ajustes compartidos DESDE %1$s A %2$s."
L["This element cannot use group-based visibility."] = "Este elemento no puede usar visibilidad basada en grupo."
L["This element doesn't support both Height and Width matching"] = "Este elemento no admite igualar a la vez el alto y el ancho"
L["This element shows as soon as ONE Show condition matches. Hide keeps its meaning in both match modes: a checked Hide always hides, on every row."] = "Este elemento se muestra en cuanto UNA condición Mostrar se cumple. Ocultar mantiene su significado en ambos modos de coincidencia: un Ocultar marcado siempre oculta, en todas las filas."
L["This element will only show while you are inside a house or plot"] = "Este elemento solo se mostrará mientras estés dentro de una casa o parcela"
L["This element will only show while you are mounted"] = "Este elemento solo se mostrará mientras vayas en montura"
L["This export includes cross profile settings that will overwrite the importing user's settings including Quality of Life, Hovercast and more that should typically not be shared with standard profiles. THIS IS NOT RECOMMENDED for public sharing of profiles."] = "Esta exportación incluye ajustes entre perfiles que sobrescribirán los ajustes del usuario que importe, incluidos Calidad de vida, Hovercast y más, que normalmente no deberían compartirse con perfiles estándar. NO SE RECOMIENDA compartir perfiles públicamente así."
L["This feature optimizes your in-game graphics settings to give you the best combination of high FPS and visual clarity.\n\nYou can revert all changes at any time by clicking \"Restore My Settings\" which will appear after optimizing.\n\n\nWhat we change:\n\n"] = "Esta función optimiza los ajustes gráficos del juego para darte la mejor combinación de FPS altos y claridad visual.\n\nPuedes revertir todos los cambios en cualquier momento haciendo clic en \"Restaurar mis ajustes\", que aparecerá tras optimizar.\n\n\nQué cambiamos:\n\n"
L["This feature requires Snap Elements to be enabled"] = "Esta función requiere que Ajustar elementos esté activado"
L["This frame's source changes require a UI reload to take effect."] = "Los cambios de origen de este marco requieren recargar la interfaz para aplicarse."
L["This glow is locked on its settings page."] = "Este resplandor está bloqueado en su página de ajustes."
L["This group's custom Buff Manager can only be activated or edited while playing one of its specs."] = "El Gestor de beneficios personalizado de este grupo solo se puede activar o editar mientras juegas con una de sus especializaciones."
L["This group's custom Debuff Manager can only be activated or edited while playing one of its specs."] = "El Gestor de perjuicios personalizado de este grupo solo se puede activar o editar mientras juegas con una de sus especializaciones."
L["This is a CDM Bar Layout string, not a profile string."] = "Esta es una cadena de diseño de barras del CDM, no una cadena de perfil."
L["This is an old CDM Bar Layout string. This format is no longer supported. Use the standard profile import instead."] = "Esta es una cadena antigua de diseño de barras del CDM. Este formato ya no es compatible. Usa la importación de perfil estándar."
L["This is the Spell Queue Window, it helps with making sure you can't queue up too many spells at once which makes the game feel laggy. Recommended settings are generally a minimum of 200 + your local ping. If you are unsure of exactly what this setting does, leave it at 400."] = "Esta es la ventana de cola de hechizos; ayuda a evitar que puedas encolar demasiados hechizos a la vez, lo que hace que el juego parezca lento. La configuración recomendada suele ser un mínimo de 200 + tu latencia local. Si no sabes exactamente qué hace este ajuste, déjalo en 400."
L["This is where you can control the settings of Unlock Mode.\n\nElements can be repositioned by dragging or arrow keys (+shift)\nAnchor, Height Match, or Width match any element.\nSnapping is based on closest element, but you can snap only to\n a specific element via right click or the settings icon."] = "Aquí puedes controlar los ajustes del Modo desbloqueo.\n\nLos elementos se pueden recolocar arrastrando o con las flechas (+Shift)\nAncla, iguala el alto o iguala el ancho de cualquier elemento.\nEl ajuste se basa en el elemento más cercano, pero puedes ajustarte solo a\n un elemento concreto con clic derecho o el icono de ajustes."
L["This makes it so the width of the cast bar includes the icon, rather than placing it to the left of the cast bars width."] = "Hace que el ancho de la barra de lanzamiento incluya el icono, en lugar de colocarlo a la izquierda del ancho de la barra."
L["This module can't be overridden. Exit the override editing session to open it."] = "Este módulo no se puede anular. Sal de la sesión de edición de anulación para abrirlo."
L["This module is excluded from Spec Overrides."] = "Este módulo está excluido de las anulaciones de especialización."
L["This option can't be used while Blizzard Class Resource Art is enabled in Resource Bars."] = "Esta opción no se puede usar mientras el arte de recurso de clase de Blizzard esté activado en Barras de recurso."
L["This option does not apply to the player frame."] = "Esta opción no se aplica al marco del jugador."
L["This option is not available on the player frame"] = "Esta opción no está disponible en el marco del jugador"
L["This option is only available for formats that display a percentage."] = "Esta opción solo está disponible para formatos que muestran un porcentaje."
L["This option is only available for the Custom Color Theme"] = "Esta opción solo está disponible para el tema de color personalizado"
L["This option is only available when Portrait Mode is Detached."] = "Esta opción solo está disponible cuando el Modo de retrato es Separado."
L["This option only affects Raid Buffs you can cast"] = "Esta opción solo afecta a los beneficios de banda que puedes lanzar"
L["This option only applies to the Badge style."] = "Esta opción solo se aplica al estilo Insignia."
L["This option only applies when Name > Target is selected."] = "Esta opción solo se aplica cuando se selecciona Nombre > Objetivo."
L["This option only applies when Name > Target or Target is selected."] = "Esta opción solo se aplica cuando se selecciona Nombre > Objetivo u Objetivo."
L["This option only applies when Target is selected."] = "Esta opción solo se aplica cuando se selecciona Objetivo."
L["This option only applies when the text shows a name."] = "Esta opción solo se aplica cuando el texto muestra un nombre."
L["This option requires a 2D Portrait or Class Art Style."] = "Esta opción requiere un estilo de arte Retrato 2D o Clase."
L["This option requires a Border Size above 0"] = "Esta opción requiere un Tamaño del borde mayor que 0"
L["This option requires a Border Size above 0."] = "Esta opción requiere un Tamaño del borde mayor que 0."
L["This option requires a Border Style other than Inherit (Main Frames)."] = "Esta opción requiere un Estilo del borde distinto de Heredar (marcos principales)."
L["This option requires a Border Style other than Solid."] = "Esta opción requiere un Estilo del borde distinto de Sólido."
L["This option requires a border style with divider art and a Border Size above 0."] = "Esta opción requiere un estilo de borde con arte divisor y un Tamaño del borde mayor que 0."
L["This option requires a Circle or Pixels Circle Shape."] = "Esta opción requiere una forma Círculo o Círculo de píxeles."
L["This option requires a Class Icon other than None."] = "Esta opción requiere un Icono de clase distinto de Ninguno."
L["This option requires a detached position to be active."] = "Esta opción requiere que haya una posición separada activa."
L["This option requires a Dispel Overlay, Color Custom Borders or Use Dispel Colors."] = "Esta opción requiere Superposición de disipación, Colorear bordes personalizados o Usar colores de disipación."
L["This option requires a dropdown selection other than Above Health Bar"] = "Esta opción requiere una selección distinta de Encima de la barra de vida"
L["This option requires a Glow Style other than None"] = "Esta opción requiere un Estilo de resplandor distinto de Ninguno"
L["This option requires a text position other than none."] = "Esta opción requiere una posición de texto distinta de ninguna."
L["This option requires a text selection other than none."] = "Esta opción requiere una selección de texto distinta de ninguna."
L["This option requires a Type Icon Position other than None"] = "Esta opción requiere una Posición del icono de tipo distinta de Ninguna"
L["This option requires a visible Portrait and Show Icon."] = "Esta opción requiere un Retrato visible y Mostrar icono."
L["This option requires an attached Power Bar, a Border Size above 0 and a border style with seam art."] = "Esta opción requiere una barra de recurso unida, un Tamaño del borde mayor que 0 y un estilo de borde con arte de unión."
L["This option requires an EllesmereUI Target or Focus frame."] = "Esta opción requiere un marco de Objetivo o Foco de EllesmereUI."
L["This option requires an Outer Ring other than None."] = "Esta opción requiere un Anillo exterior distinto de Ninguno."
L["This option requires Art Style to be set to Class"] = "Esta opción requiere que el Estilo de arte sea Clase"
L["This option requires Blizzard Style to be disabled"] = "Esta opción requiere que el Estilo Blizzard esté desactivado"
L["This option requires Class Resource to be set to Modern."] = "Esta opción requiere que Recurso de clase esté en Moderno."
L["This option requires Combine Spell Name and Target to be disabled."] = "Esta opción requiere que Combinar nombre del hechizo y objetivo esté desactivado."
L["This option requires Custom Border Style, Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Esta opción requiere Estilo de borde personalizado, Mostrar icono y Hacer el icono parte de la barra, con el estilo EllesmereUI."
L["This option requires Dispel Type Borders to be enabled."] = "Esta opción requiere que los Bordes por tipo de disipación estén activados."
L["This option requires Portrait Mode to be set to Detached."] = "Esta opción requiere que el Modo de retrato esté en Separado."
L["This option requires Show Icon and Make Icon Part of the Bar, with the EllesmereUI style."] = "Esta opción requiere Mostrar icono y Hacer el icono parte de la barra, con el estilo EllesmereUI."
L["This option requires Show Icon and the EllesmereUI style."] = "Esta opción requiere Mostrar icono y el estilo EllesmereUI."
L["This option requires Show Icon beside the cast bar and the EllesmereUI style."] = "Esta opción requiere Mostrar icono junto a la barra de lanzamiento y el estilo EllesmereUI."
L["This option requires Show Level."] = "Esta opción requiere Mostrar nivel."
L["This option requires Solid or a border style with divider art, and a Border Size above 0."] = "Esta opción requiere Sólido o un estilo de borde con arte divisor, y un Tamaño del borde mayor que 0."
L["This option requires the Class Art Style."] = "Esta opción requiere el estilo de arte Clase."
L["This option requires the Class Colored Shape Border and Dark Mode."] = "Esta opción requiere el Borde de forma con color de clase y el Modo oscuro."
L["This option requires the position setting to be detached"] = "Esta opción requiere que el ajuste de posición esté separado"
L["This option requires the WoW Forever style."] = "Esta opción requiere el estilo WoW Forever."
L["This overwrites this frame's current settings. Frame position, visibility, and enable state are not changed."] = "Esto sobrescribe los ajustes actuales de este marco. La posición, la visibilidad y el estado de activación del marco no cambian."
L["This page is excluded from overrides."] = "Esta página está excluida de las anulaciones."
L["This permanently overwrites this profile's settings with the override '%s': its captured settings and its custom Unlock Mode and Buff Manager layouts (where present) become the profile's own baseline for every spec. ALL spec override groups on this profile are then deleted and the UI reloads. Conditional overrides are not affected."] = "Esto sobrescribe permanentemente los ajustes de este perfil con la anulación '%s': sus ajustes capturados y sus diseños personalizados de Modo desbloqueo y Gestor de beneficios (si existen) pasan a ser la base propia del perfil para todas las especializaciones. Después se eliminan TODOS los grupos de anulación por especialización de este perfil y la interfaz se recarga. Las anulaciones condicionales no se ven afectadas."
L["This profile string does not carry any global settings."] = "Esta cadena de perfil no contiene ajustes globales."
L["This profile string does not carry any override data."] = "Esta cadena de perfil no contiene datos de anulación."
L["This profile string does not carry any Window & Tooltip Skins settings."] = "Esta cadena de perfil no contiene ajustes de Aspecto de ventanas y descripciones."
L["This profile was created before the beta wipe and is no longer compatible. Please create a new export."] = "Este perfil se creó antes del reinicio de la beta y ya no es compatible. Crea una nueva exportación."
L["This profile was created with a newer version of EllesmereUI. Please update your addon."] = "Este perfil se creó con una versión más reciente de EllesmereUI. Actualiza el addon."
L["This profile was made at %1$d%% UI scale; yours is %2$d%%. Change your UI scale to match the imported profile? This will show all profiles at this scale as UI Scale is not a per-profile setting, but can be changed at any time back to your original value."] = "Este perfil se hizo con una escala de interfaz del %1$d%%; la tuya es del %2$d%%. ¿Cambiar tu escala de interfaz para que coincida con el perfil importado? Todos los perfiles se mostrarán a esta escala, ya que la escala de la interfaz no es un ajuste por perfil, pero puedes volver a tu valor original en cualquier momento."
L["This resets every EUI addon, not just the current one."] = "Esto restablece todos los addons de EUI, no solo el actual."
L["This setting already has an override for %s"] = "Este ajuste ya tiene una anulación para %s"
L["This setting can't be overridden."] = "Este ajuste no se puede anular."
L["This Setting Has Overrides"] = "Este ajuste tiene anulaciones"
L["This spec's custom unlock mode is owned by '%s'. Customize it there, or remove the spec from that group."] = "El Modo desbloqueo personalizado de esta especialización pertenece a '%s'. Personalízalo allí o quita la especialización de ese grupo."
L["This string is a FULL ACCOUNT export. It replaces your account-wide settings with the sender's, including Quality of Life, HoverCast bindings, Cooldown Manager spell setups, unlock anchors, UI scale, and profile keybinds -- not just a profile. Your other profiles are kept, but a profile with the same name is replaced."] = "Esta cadena es una exportación de CUENTA COMPLETA. Sustituye tus ajustes de toda la cuenta por los del remitente, incluidos Calidad de vida, atajos de HoverCast, configuraciones de hechizos del Gestor de reutilización, anclajes de desbloqueo, escala de la interfaz y atajos de perfil, no solo un perfil. Tus otros perfiles se conservan, pero un perfil con el mismo nombre se reemplaza."
L["This unit uses the Blizzard default frame -- there are no EllesmereUI settings to configure here."] = "Esta unidad usa el marco predeterminado de Blizzard: no hay ajustes de EllesmereUI que configurar aquí."
L["This unit's frame is hidden -- there are no EllesmereUI settings to configure here."] = "El marco de esta unidad está oculto: no hay ajustes de EllesmereUI que configurar aquí."
L["This will create a fully unique Buff Manager for this conditional group. Changes made to your default Buff Manager will no longer affect it."] = "Esto creará un Gestor de beneficios totalmente único para este grupo condicional. Los cambios en tu Gestor de beneficios predeterminado ya no le afectarán."
L["This will create a fully unique Buff Manager for this override group. Changes made to your default Buff Manager will no longer affect these specs."] = "Esto creará un Gestor de beneficios totalmente único para este grupo de anulación. Los cambios en tu Gestor de beneficios predeterminado ya no afectarán a estas especializaciones."
L["This will create a fully unique Debuff Manager for this conditional group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect it."] = "Esto creará un Gestor de perjuicios totalmente único para este grupo condicional. Tus ajustes actuales del Gestor de perjuicios se copian como punto de partida, y los cambios en tu Gestor de perjuicios predeterminado ya no le afectarán."
L["This will create a fully unique Debuff Manager for this override group. Your current Debuff Manager settings are copied as its starting point, and changes made to your default Debuff Manager will no longer affect these specs."] = "Esto creará un Gestor de perjuicios totalmente único para este grupo de anulación. Tus ajustes actuales del Gestor de perjuicios se copian como punto de partida, y los cambios en tu Gestor de perjuicios predeterminado ya no afectarán a estas especializaciones."
L["This will create a fully unique unlock mode for this conditional group. Changes made to your default unlock mode will no longer affect it."] = "Esto creará un Modo desbloqueo totalmente único para este grupo condicional. Los cambios en tu Modo desbloqueo predeterminado ya no le afectarán."
L["This will create a fully unique unlock mode for this override group. Changes made to your default unlock mode will no longer affect these specs."] = "Esto creará un Modo desbloqueo totalmente único para este grupo de anulación. Los cambios en tu Modo desbloqueo predeterminado ya no afectarán a estas especializaciones."
L["This will not reset addon-specific Quick Setup."] = "Esto no restablecerá la Configuración rápida específica de cada addon."
L["This will replace YOUR Blizz UI Enhanced settings (the Window Skins and Tooltips, Menus & Popups tabs) with the sharer's, across ALL of your profiles. Your current settings on those two tabs cannot be recovered afterward."] = "Esto reemplazará TUS ajustes de Interfaz Blizz mejorada (las pestañas Aspecto de ventanas y Descripciones, menús y ventanas emergentes) por los de quien comparte, en TODOS tus perfiles. Tus ajustes actuales de esas dos pestañas no se podrán recuperar después."
L["This would create a circular anchor"] = "Esto crearía un anclaje circular"
L["This would create a circular height match"] = "Esto crearía una igualación de alto circular"
L["This would create a circular width match"] = "Esto crearía una igualación de ancho circular"
