L["When your interrupt is on cooldown now but will be ready before the enemy cast finishes, color the part of the cast bar during which your interrupt will be available. The color clears the instant your interrupt comes off cooldown."] = "Cuando tu interrupción está en reutilización pero estará lista antes de que termine el lanzamiento enemigo, colorea la parte de la barra de lanzamiento durante la que tu interrupción estará disponible. El color desaparece en cuanto tu interrupción sale de reutilización."
