L["Your current spec has its own custom unlock mode, so conditional unlock modes never apply to it. Swap to a spec without one to customize this."] = "Tu especialización actual tiene su propio Modo desbloqueo personalizado, así que los modos desbloqueo condicionales nunca se le aplican. Cambia a una especialización sin uno para personalizar esto."
L["Your heals"] = "Tus sanaciones"
L["Your preferred food is out - using a backup you own"] = "Tu comida preferida se agotó; usando una de reserva que tienes"
L["Your setup and every EllesmereUI feature carry over; only the look changes. Apply a style to every module in one click, or set each module below. Changing a style reloads the UI."] = "Tu configuración y todas las funciones de EllesmereUI se conservan; solo cambia el aspecto. Aplica un estilo a todos los módulos con un clic o configura cada módulo abajo. Cambiar un estilo recarga la UI."
L["Your UI, Restyled in Seconds"] = "Tu UI, renovada en segundos"
