L["|cff00ff00[EllesmereUI]|r All hints reset. /reload to see them again."] = "|cff00ff00[EllesmereUI]|r Todas las pistas restablecidas. Usa /reload para verlas de nuevo."
L["|cff00ff00[EllesmereUI]|r UI scale reset. /reload to re-snapshot from your Blizzard scale."] = "|cff00ff00[EllesmereUI]|r Escala de la UI restablecida. Usa /reload para volver a tomarla de tu escala de Blizzard."
L["|cff00ff98EllesmereUI:|r Overrides intro reset. The announcement popup fires on your next /reload; the video guide fires on your next click of the overrides glyph."] = "|cff00ff98EllesmereUI:|r Introducción de anulaciones restablecida. El aviso emergente aparecerá en tu próximo /reload; la videoguía aparecerá en tu próximo clic en el glifo de anulaciones."
L["|cff00ff98EllesmereUI:|r Video guides and tutorial tips reset. Badges are back; one-time popups will fire again."] = "|cff00ff98EllesmereUI:|r Videoguías y consejos del tutorial restablecidos. Las insignias han vuelto; los avisos de una sola vez aparecerán de nuevo."
L["|cff0cd29dLeft-click:|r |cffE0E0E0Toggle EllesmereUI|r"] = "|cff0cd29dClic izquierdo:|r |cffE0E0E0Mostrar/ocultar EllesmereUI|r"
L["|cff0cd29dMiddle-click:|r |cffE0E0E0Hide Minimap Button|r"] = "|cff0cd29dClic central:|r |cffE0E0E0Ocultar botón del minimapa|r"
L["|cff0cd29dRight-click:|r |cffE0E0E0Enter Unlock Mode|r"] = "|cff0cd29dClic derecho:|r |cffE0E0E0Entrar en Modo desbloqueo|r"
L["|cff888888...and %d more|r"] = "|cff888888...y %d más|r"
L["|cffff6060[EllesmereUI]|r A profile named \"%1$s\" already exists."] = "|cffff6060[EllesmereUI]|r Ya existe un perfil llamado \"%1$s\"."
L["|cffff6060[EllesmereUI]|r Cannot enter Unlock Mode during combat."] = "|cffff6060[EllesmereUI]|r No se puede entrar en Modo desbloqueo en combate."
L["|cffff6060[EllesmereUI]|r Cannot open options during combat. Use /eui to view Patch Notes."] = "|cffff6060[EllesmereUI]|r No se pueden abrir las opciones en combate. Usa /eui para ver las notas del parche."
L["|cffff6060[EllesmereUI]|r Cannot rename to \"Default\"."] = "|cffff6060[EllesmereUI]|r No se puede renombrar a \"Default\"."
L["|cffff6060[EllesmereUI]|r Spec changed: Unlock Mode closed, unsaved layout changes discarded."] = "|cffff6060[EllesmereUI]|r Especialización cambiada: Modo desbloqueo cerrado, cambios de diseño sin guardar descartados."
L["|cffFFFFFFCtrl + Alt + Left Click:|r"] = "|cffFFFFFFCtrl + Alt + Clic izquierdo:|r"
L["|cffFFFFFFCtrl + Left Click:|r"] = "|cffFFFFFFCtrl + Clic izquierdo:|r"
L["|cffFFFFFFCtrl + Right Click:|r"] = "|cffFFFFFFCtrl + Clic derecho:|r"
