L["简体中文 (Simplified Chinese)"] = "简体中文 (chino simplificado)"
L["繁體中文 (Traditional Chinese)"] = "繁體中文 (chino tradicional)"
L["한국어 (Korean)"] = "한국어 (coreano)"
L["A blank bar to build from scratch."] = "Una barra vacía para crear desde cero."
L["A bright spark at the edge of the fill."] = "Una chispa brillante en el borde del relleno."
L["A friendly focus wins over the tank. The focus is checked at the moment you press it, also in combat."] = "Un foco amistoso tiene prioridad sobre el tanque. El foco se comprueba en el momento de pulsarlo, también en combate."
L["A group member to use as the tank. Empty uses the raid Main Tank, then the Dungeon Finder tank role. Updates out of combat."] = "Un miembro del grupo para usar como tanque. Vacío usa el tanque principal de la banda y luego el rol de tanque del Buscador de mazmorras. Se actualiza fuera de combate."
L["A line at every 10% and a tick at every 5% across the bar."] = "Una línea cada 10% y una marca cada 5% a lo largo de la barra."
L["A raid control panel with ready check, pull timer and target markers. In a raid it only shows while you are the leader or an assistant, since none of its buttons work without that; in a party it always shows."] = "Un panel de control de banda con comprobación de disponibilidad, temporizador de pull y marcadores de objetivo. En una banda solo se muestra si eres el líder o un ayudante, ya que ninguno de sus botones funciona sin eso; en un grupo siempre se muestra."
L["Abbreviate Numbers"] = "Abreviar números"
L["Animation"] = "Animación"
L["Apply Styles"] = "Aplicar estilos"
