L["Blizz Default also switches the reputation bar to Blizzard's."] = "Predeterminado de Blizz también cambia la barra de reputación a la de Blizzard."
L["Both Specs"] = "Ambas especializaciones"
L["Bright line on the swipe edge (needs a client with Cooldown:SetDrawEdge; native swipe only)."] = "Línea brillante en el borde del barrido (requiere un cliente con Cooldown:SetDrawEdge; solo barrido nativo)."
L["Buff Icon Size"] = "Tamaño de icono de beneficio"
L["Buff X Offset"] = "Desplazamiento X de beneficios"
