L["Clear Focus Click"] = "Clic para quitar foco"
L["Clear Markers"] = "Borrar marcadores"
L["Clear World Markers"] = "Borrar marcadores de mundo"
L["Clears your focus when you click the focus frame this way. Works in combat, where the right-click menu cannot clear focus."] = "Quita tu foco al hacer clic de esta forma en el marco de foco. Funciona en combate, donde el menú del clic derecho no puede quitar el foco."
L["Close Edit Mode first, then try again."] = "Cierra primero el Modo edición e inténtalo de nuevo."
L["Combat Color"] = "Color de combate"
L["Compact Band"] = "Banda compacta"
L["Compact Band puts markers, ready check and pull timer in one row you can resize in Unlock Mode. The other choices keep the window layouts."] = "Banda compacta pone los marcadores, la comprobación de disponibilidad y el temporizador de pull en una fila que puedes redimensionar en el Modo desbloqueo. Las demás opciones mantienen los diseños de ventana."
L["Compact clock and FPS readout."] = "Reloj compacto e indicador de FPS."
L["Completed quest XP shows ahead of the fill in green, incomplete quest XP after it in gold. Quests under collapsed quest log headers are not counted."] = "La PX de misiones completadas se muestra delante del relleno en verde, y la de misiones incompletas detrás en dorado. No se cuentan las misiones bajo encabezados contraídos del registro de misiones."
L["Completed quests"] = "Misiones completadas"
L["Completed Quests Only"] = "Solo misiones completadas"
L["Countdown length in seconds. Compact Band uses First with Ctrl + Left Click, Second with Shift + Left Click, Third with Left Click, and Right Click stops the timer. Set a timer to 0 to disable that shortcut."] = "Duración de la cuenta atrás en segundos. Banda compacta usa el primero con Ctrl + Clic izquierdo, el segundo con Shift + Clic izquierdo, el tercero con Clic izquierdo, y Clic derecho detiene el temporizador. Pon un temporizador a 0 para desactivar ese atajo."
