L["Full-window modes only. Shows start as a small icon, and the keybind switches between the icon and the full windows."] = "Solo modos de ventana completa. Empieza mostrándose como un icono pequeño, y el atajo alterna entre el icono y las ventanas completas."
L["Full-window modes only. Which way the windows extend from the collapsed icon when they open."] = "Solo modos de ventana completa. Hacia dónde se extienden las ventanas desde el icono contraído al abrirse."
