L["Hide Sated / Exhaustion"] = "Ocultar Saciado / Agotamiento"
L["Hide Until Usable"] = "Ocultar hasta que sea usable"
L["Hide Until Usable (Keep Place)"] = "Ocultar hasta que sea usable (mantener posición)"
L["Hide Until Usable: only shown while usable and off cooldown, such as Overpower or Victory Rush after a proc; low resources do not hide it. Hide Outside Form/Stance: only shown in the form or stance the spell needs, even on cooldown. Keep Place leaves the gap; the others close it."] = "Ocultar hasta que sea usable: solo se muestra mientras se pueda usar y no esté en reutilización, como Abrumar o Ataque victorioso tras un proc; la falta de recursos no lo oculta. Ocultar fuera de forma/actitud: solo se muestra en la forma o actitud que necesita el hechizo, incluso en reutilización. Mantener posición deja el hueco; los demás lo cierran."
L["Hides the Bloodlust and Heroism lockout debuffs."] = "Oculta los perjuicios de bloqueo de Ansia de sangre y Heroísmo."
L["Highlight Items on Stat Hover"] = "Resaltar objetos al pasar sobre estadísticas"
L["Hovering a stat in the sidebar glows the equipped items that give it (Hit, Crit, Haste, Defense, Strength...)."] = "Al pasar el ratón sobre una estadística de la barra lateral, brillan los objetos equipados que la otorgan (Golpe, Crítico, Celeridad, Defensa, Fuerza...)."
L["Hunters and Rogues: an icon you click (or bind in Key Bindings > EllesmereUI Quality of Life) that casts Misdirection or Tricks of the Trade on your focus, else the tank, else a friendly target"] = "Cazadores y pícaros: un icono en el que haces clic (o asignas en Asignación de teclas > EllesmereUI Quality of Life) que lanza Redirección o Secretos del oficio sobre tu foco, si no sobre el tanque, si no sobre un objetivo amistoso"
L["Ignore Low Level Quests"] = "Ignorar misiones de nivel bajo"
