L["Native"] = "Nativo"
L["Native: the client's dark square sweep. Shaped: a drawn sweep that follows round icons and takes the Swipe Color."] = "Nativo: el barrido cuadrado oscuro del cliente. Con forma: un barrido dibujado que sigue los iconos redondos y usa el Color del barrido."
L["Nest Distance"] = "Distancia de anidado"
