L["Own and Raid Debuffs"] = "Perjuicios propios y de banda"
L["Own Keybind"] = "Atajo propio"
L["Percent of the end caps' normal size."] = "Porcentaje del tamaño normal de los remates."
L["Picks an NPC's only dialog option for you."] = "Elige por ti la única opción de diálogo de un PNJ."
L["Player Buffs on Tooltips"] = "Beneficios del jugador en descripciones"
L["Positive values move both end caps away from the bar."] = "Los valores positivos alejan ambos remates de la barra."
L["Primary Spec"] = "Especialización principal"
L["PULL TIMER"] = "TEMPORIZADOR DE PULL"
L["Pushes older messages along so a new one never overlaps them."] = "Desplaza los mensajes anteriores para que uno nuevo nunca se solape con ellos."
L["Quest XP Overlay"] = "Superposición de PX de misiones"
L["Raid Debuffs Filter"] = "Filtro de perjuicios de banda"
L["Raid Debuffs shows the common raid debuffs (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements, Hunter's Mark) from anyone."] = "Perjuicios de banda muestra los perjuicios de banda comunes (armadura, daño de hechizos y físico recibido, críticos recibidos, poder de ataque, velocidad de ataque y lanzamiento, sanación recibida, Sentencias, Marca del cazador) de cualquiera."
L["Reads the item's own stats; enchants and gems are not counted."] = "Lee las estadísticas propias del objeto; no se cuentan encantamientos ni gemas."
L["Reload to finish resetting EUI."] = "Recarga para terminar de restablecer EUI."
L["Reload to finish uninstalling EUI."] = "Recarga para terminar de desinstalar EUI."
L["Rename DataBar"] = "Renombrar DataBar"
L["Rested After Quest XP"] = "Descanso tras PX de misiones"
L["Rested color"] = "Color de descanso"
L["Return every EUI addon to its defaults."] = "Devuelve todos los addons de EUI a sus valores predeterminados."
L["Revert EUI's changes and disable."] = "Revierte los cambios de EUI y lo desactiva."
L["Right Endcap"] = "Remate derecho"
L["Scroll Distance"] = "Distancia de desplazamiento"
L["Second Timer"] = "Segundo temporizador"
L["Secondary Spec"] = "Especialización secundaria"
L["Selection Color"] = "Color de selección"
L["Selection Color: Custom Color"] = "Color de selección: color personalizado"
L["SELF COMBAT TEXT"] = "TEXTO DE COMBATE PROPIO"
L["Self Combat Text"] = "Texto de combate propio"
L["Sell Junk skips items with no vendor price, equipment set gear and pinned items."] = "Vender basura omite los objetos sin precio de venta, el equipo de conjuntos de equipamiento y los objetos fijados."
L["Shaped"] = "Con forma"
L["Shaped Cooldown Swipe"] = "Barrido de reutilización con forma"
L["Share Keybind With"] = "Compartir atajo con"
L["Shift + Click World Markers"] = "Shift + Clic en marcadores de mundo"
L["Shift + Left Click a marker icon to use its world marker item, then click the ground. Only markers whose item is in your bags get it; the rest keep Shift + Click to clear the target marker. Shift + Left Click the clear icon presses the server's Reset Markers button."] = "Shift + Clic izquierdo en un icono de marcador usa su objeto de marcador de mundo; luego haz clic en el suelo. Solo lo obtienen los marcadores cuyo objeto está en tus bolsas; el resto mantiene Shift + Clic para borrar el marcador de objetivo. Shift + Clic izquierdo en el icono de borrar pulsa el botón Restablecer marcadores del servidor."
L["Show a small coin in the corner of items marked as junk."] = "Muestra una pequeña moneda en la esquina de los objetos marcados como basura."
L["Show as"] = "Mostrar como"
L["Show at Max Level"] = "Mostrar al nivel máximo"
L["Show Coin on Junk"] = "Mostrar moneda en la basura"
L["Show Convert to Raid"] = "Mostrar Convertir en banda"
L["Show Disband"] = "Mostrar Disolver"
L["Show Dividers"] = "Mostrar divisores"
L["Show Equipped Item Color"] = "Mostrar color del objeto equipado"
L["Show Inspect Enchant Names Instead of Icons"] = "Mostrar nombres de encantamientos en inspección en lugar de iconos"
L["Show Item Icon Name"] = "Mostrar nombre del icono del objeto"
L["Show Item ID on Tooltip"] = "Mostrar ID de objeto en la descripción"
L["Show Player Buffs"] = "Mostrar beneficios del jugador"
L["Show Reinvite"] = "Mostrar Reinvitar"
L["Show Rested XP"] = "Mostrar PX de descanso"
L["Show Target Name"] = "Mostrar nombre del objetivo"
L["Show the coin button in the bag header. Click it, then click items to mark or unmark them as junk. Junk goes into its own Junk category, and a Sell Junk button appears next to the coin while a merchant is open."] = "Muestra el botón de la moneda en el encabezado de las bolsas. Haz clic en él y luego en los objetos para marcarlos o desmarcarlos como basura. La basura va a su propia categoría Basura, y aparece un botón Vender basura junto a la moneda mientras hay un vendedor abierto."
L["Shown at max level. Profession bonuses are only checked on your own sheet."] = "Se muestra al nivel máximo. Las bonificaciones de profesión solo se comprueban en tu propia hoja."
L["Shows the common raid debuffs from anyone: armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark."] = "Muestra los perjuicios de banda comunes de cualquiera: armadura, daño de hechizos y físico recibido, críticos recibidos, poder de ataque, velocidad de ataque y lanzamiento, sanación recibida, Sentencias y Marca del cazador."
L["Shows the Convert to Raid button. In a raid of five or fewer it reads Convert to Party: everyone is removed and invited back to a new party."] = "Muestra el botón Convertir en banda. En una banda de cinco o menos se lee Convertir en grupo: se expulsa a todos y se les vuelve a invitar a un grupo nuevo."
L["Shows the debuffs you apply plus the common raid debuffs from anyone."] = "Muestra los perjuicios que aplicas más los perjuicios de banda comunes de cualquiera."
L["Shows the Disband button. It always asks before disbanding, but hiding it puts it out of misclick range for good."] = "Muestra el botón Disolver. Siempre pregunta antes de disolver, pero ocultarlo lo pone definitivamente fuera del alcance de clics accidentales."
L["Shows the hovered player's buffs as icons next to the tooltip (up to 16)."] = "Muestra los beneficios del jugador señalado como iconos junto a la descripción (hasta 16)."
L["Shows the overlay, type icon and border colors only for debuffs you can currently dispel."] = "Muestra la superposición, el icono de tipo y los colores de borde solo para los perjuicios que puedes disipar en ese momento."
L["Shows the Reinvite button. It asks first, then removes everyone and invites them back to the same kind of group. Players have to accept the new invite."] = "Muestra el botón Reinvitar. Pregunta primero, luego expulsa a todos y los vuelve a invitar al mismo tipo de grupo. Los jugadores tienen que aceptar la nueva invitación."
L["Shows your damage taken, healing, avoids and combat enter/leave above the player frame instead of Blizzard's combat text, whose other messages are hidden while this is on. Move it in Unlock Mode."] = "Muestra tu daño recibido, sanación, evitaciones y entrada/salida de combate sobre el marco del jugador en lugar del texto de combate de Blizzard, cuyos demás mensajes se ocultan mientras esto está activo. Muévelo en el Modo desbloqueo."
L["Smart Ticks"] = "Marcas inteligentes"
L["Spell IDs in the Breakdown"] = "ID de hechizo en el desglose"
L["Spell Power"] = "Poder con hechizos"
L["Stagger Hits"] = "Escalonar golpes"
L["Stat Hover Highlight"] = "Resaltado al pasar sobre estadísticas"
L["Static"] = "Estático"
L["Straight"] = "Recto"
L["Style Page Look Menus"] = "Menús de aspecto de la página Estilo"
L["Swipe Color"] = "Color del barrido"
L["Swipe Style"] = "Estilo del barrido"
L["Tank Name"] = "Nombre del tanque"
L["Text Shadow"] = "Sombra del texto"
L["The [Merfin] Experience Bar (Luxthos) WeakAura: blue to purple gradient, Quest XP Overlay, spark, rested after quest XP and seven texts with level, times and time to level."] = "La WeakAura [Merfin] Experience Bar (Luxthos): degradado de azul a morado, superposición de PX de misiones, chispa, descanso tras PX de misiones y siete textos con nivel, tiempos y tiempo hasta subir de nivel."
L["The classic tooltip box around the meter window, with vanilla header buttons and every EllesmereUI meter feature."] = "El recuadro clásico de descripción alrededor de la ventana del medidor, con botones de encabezado vanilla y todas las funciones del medidor de EllesmereUI."
L["The gap between a nested menu's icons and the entry that opens it."] = "La separación entre los iconos de un menú anidado y la entrada que lo abre."
L["The rested segment starts where the Quest XP Overlay ends instead of at your current XP."] = "El segmento de descanso empieza donde termina la superposición de PX de misiones en lugar de en tu PX actual."
L["The talent group this action menu works in. Outside it the keybind does nothing and the menu is hidden where it is nested."] = "El grupo de talentos en el que funciona este menú de acciones. Fuera de él, el atajo no hace nada y el menú se oculta donde esté anidado."
L["Third Timer"] = "Tercer temporizador"
L["This option requires an EllesmereUI Focus frame."] = "Esta opción requiere un marco de foco de EllesmereUI."
L["This option requires XP Bar Style EllesmereUI or Luxthos"] = "Esta opción requiere el estilo de barra de PX EllesmereUI o Luxthos"
L["Time This Session and XP per Hour carry on through a /reload (a load within five minutes) instead of starting over."] = "Tiempo en esta sesión y PX por hora continúan tras un /reload (una carga en menos de cinco minutos) en lugar de empezar de cero."
L["Timed Buffs"] = "Beneficios con duración"
L["Toggle Raid Tools"] = "Alternar herramientas de banda"
L["Toggles the Raid Tools panels, in or out of combat.\n\nLeft-click to set a keybind.\nRight-click to unbind."] = "Alterna los paneles de herramientas de banda, dentro o fuera de combate.\n\nClic izquierdo para asignar un atajo.\nClic derecho para quitarlo."
L["Two Windows"] = "Dos ventanas"
L["Uninstall & Reload"] = "Desinstalar y recargar"
L["Uninstall EUI"] = "Desinstalar EUI"
L["Up Left"] = "Arriba a la izquierda"
L["Up Right"] = "Arriba a la derecha"
L["Use another action menu's keybind while that menu is not loaded. Both menus must be assigned to different specs."] = "Usa el atajo de otro menú de acciones mientras ese menú no está cargado. Ambos menús deben estar asignados a especializaciones distintas."
L["Which buffs enemy nameplates show. Fine-tune it on the Aura Filters page."] = "Qué beneficios muestran las placas de nombre enemigas. Ajústalo con detalle en la página Filtros de auras."
L["Which ends of the bar show the gryphons."] = "En qué extremos de la barra se muestran los grifos."
L["XP Bar Style"] = "Estilo de barra de PX"
L["XP color"] = "Color de PX"
L["Every module runs on native Wrath APIs. Retail looks and settings were ported wherever the 3.3.5a client supports them, and Retail-only systems were left out. Notes are grouped by module, newest first, and each header shows that module's backport version."] = "Todos los módulos funcionan con las API nativas de Wrath. El aspecto y los ajustes de Retail se han portado allí donde el cliente 3.3.5a los admite, y los sistemas exclusivos de Retail se han dejado fuera. Las notas están agrupadas por módulo, de más reciente a más antigua, y cada encabezado muestra la versión del backport de ese módulo."
L["Icons beside each enemy for every crowd control category they are under or recovering from: green means the next one lasts half as long, yellow a quarter, red immune. A timer shows the 18 second reset."] = "Iconos junto a cada enemigo por cada categoría de control de masas que sufre o de la que se está recuperando: verde significa que el siguiente dura la mitad, amarillo una cuarta parte, rojo inmune. Un temporizador muestra el reinicio de 18 segundos."
L["A health bar for each enemy pet under its owner's frame. Left-click targets the pet, right-click sets focus."] = "Una barra de vida para cada mascota enemiga bajo el marco de su dueño. Clic izquierdo selecciona la mascota, clic derecho la pone como foco."
L["Enemy frames for arena1-5 with class colored health, power and cast bars plus a highlight on your target. Left-click targets, right-click sets focus. There is no Retail equivalent."] = "Marcos enemigos para arena1-5 con barras de vida, recurso y lanzamiento con color de clase y un resaltado en tu objetivo. Clic izquierdo selecciona, clic derecho pone foco. No hay equivalente en Retail."
L["The class icon swaps to the highest priority crowd control or immunity with a spiral and timer, and the PvP trinket icon tracks its 2 minute cooldown from the combat log."] = "El icono de clase cambia al control de masas o inmunidad de mayor prioridad con una espiral y un temporizador, y el icono del abalorio JcJ sigue su reutilización de 2 minutos desde el registro de combate."
L["Bar Texture lists textures from SharedMedia and other addons using LibSharedMedia"] = "Textura de barra muestra texturas de SharedMedia y de otros addons que usan LibSharedMedia"
L["Enemies beyond your class's 30-40 yard spell range fade to a chosen opacity"] = "Los enemigos fuera del alcance de hechizos de 30-40 metros de tu clase se atenúan a una opacidad elegida"
L["Preview 2 to 5 sample frames in Unlock Mode, while the options page is open, or with /earena test"] = "Previsualiza de 2 a 5 marcos de muestra en el Modo desbloqueo, mientras la página de opciones está abierta o con /earena test"
L["Frames stay up while an enemy is stealthed or out of sight, dimmed and marked Unseen"] = "Los marcos siguen visibles mientras un enemigo está en sigilo o fuera de vista, atenuados y marcados como No visto"
L["Optionally hides Blizzard's arena frames while these are in use"] = "Opcionalmente oculta los marcos de arena de Blizzard mientras se usan estos"
L["The Debuff Filter gets Raid Debuffs and Own and Raid Debuffs, with the same raid debuff list as the Unit Frames."] = "El Filtro de perjuicios obtiene Perjuicios de banda y Perjuicios propios y de banda, con la misma lista de perjuicios de banda que los Marcos de unidad."
L["Choose which buffs enemy nameplates show: Timed Buffs, Only Dispellable or Show All, which shows every buff."] = "Elige qué beneficios muestran las placas de nombre enemigas: Beneficios con duración, Solo disipables o Mostrar todo, que muestra todos los beneficios."
L["Every nameplate text has an Outline choice under its Size: None, Outline, Thick Outline or Shadow, or keep the module default. Covers names, level, health, Target of Target, cast texts, aura text and friendly names."] = "Cada texto de las placas de nombre tiene una opción de Contorno bajo su Tamaño: Ninguno, Contorno, Contorno grueso o Sombras, o mantener el predeterminado del módulo. Abarca nombres, nivel, vida, Objetivo del objetivo, textos de lanzamiento, texto de auras y nombres amistosos."
L["Cast bars now fill every frame instead of stepping with each nameplate refresh. The spark and timer move smoothly too, and the extra work stops when no cast is visible."] = "Las barras de lanzamiento ahora se rellenan en cada fotograma en lugar de avanzar a saltos con cada actualización de la placa. La chispa y el temporizador también se mueven con suavidad, y el trabajo extra se detiene cuando no hay ningún lanzamiento visible."
L["Core Text Positions offers all Retail texts: Enemy Name, Level | Name, Target of Target, Health % and Health # with their combined variants. Each text's cog sets its size."] = "Posiciones de textos principales ofrece todos los textos de Retail: Nombre del enemigo, Nivel | Nombre, Objetivo del objetivo, Vida % y Vida # con sus variantes combinadas. El engranaje de cada texto ajusta su tamaño."
L["Health and cast bars offer the EllesmereUI textures (Melli, Atrocity, Fade, Matte and more), as on Retail"] = "Las barras de vida y lanzamiento ofrecen las texturas de EllesmereUI (Melli, Atrocity, Fade, Matte y más), como en Retail"
L["Health and cast bar textures include textures from SharedMedia and other addons"] = "Las texturas de las barras de vida y lanzamiento incluyen texturas de SharedMedia y de otros addons"
L["Display and Colors show a live preview plate; click any part of it to jump to its setting"] = "Visualización y Colores muestran una placa de vista previa en vivo; haz clic en cualquier parte de ella para saltar a su ajuste"
L["Retail bar size, colors, threat modes, cast colors, target arrows and Execute Pulse Glow"] = "Tamaño de barra, colores, modos de amenaza, colores de lanzamiento, flechas de objetivo y Resplandor pulsante de ejecución de Retail"
L["Each slot holds one element; auras, raid marker and classification can also sit below the cast bar"] = "Cada casilla contiene un elemento; las auras, el marcador de banda y la clasificación también pueden ir debajo de la barra de lanzamiento"
L["Health # uses Blizzard style abbreviations (1.2K, 12K, 1.2M) with an optional % decimal"] = "Vida # usa abreviaturas al estilo de Blizzard (1.2K, 12K, 1.2M) con un decimal de % opcional"
L["A profile imported from Retail no longer blows the target nameplate up to fill the screen."] = "Un perfil importado de Retail ya no agranda la placa de nombre del objetivo hasta llenar la pantalla."
L["Border None now hides only the borders, not the cast bar text, timer, shield and kick mark."] = "Borde Ninguno ahora oculta solo los bordes, no el texto de la barra de lanzamiento, el temporizador, el escudo ni la marca de interrupción."
L["The options preview plate no longer disappears after switching tabs or closing the panel."] = "La placa de vista previa de las opciones ya no desaparece al cambiar de pestaña o cerrar el panel."
L["The Interrupt on CD cast color now shows while your interrupt recharges, as on Retail, instead of the reverse."] = "El color de lanzamiento Interrupción en reutilización ahora se muestra mientras tu interrupción se recarga, como en Retail, en lugar de al revés."
L["Raid and party names each get their own outline: None, Outline, Thick Outline, Shadow, or the Raid Frames font default."] = "Los nombres de banda y de grupo tienen cada uno su propio contorno: Ninguno, Contorno, Contorno grueso, Sombras o el predeterminado de la fuente de los Marcos de banda."
L["A new Group Layout stacks two raid groups per column, then starts the next column to the right, so a 20-player raid forms a 2x2 block."] = "Una nueva Disposición del grupo apila dos grupos de banda por columna y luego empieza la siguiente columna a la derecha, de modo que una banda de 20 jugadores forma un bloque de 2x2."
L["Ready check icons appear above debuffs and keep each player result for ten seconds after the check finishes."] = "Los iconos de comprobación de disponibilidad aparecen sobre los perjuicios y mantienen el resultado de cada jugador durante diez segundos tras terminar la comprobación."
L["The debuff displayed in the central Raid Debuff icon is excluded from the regular debuff bar, leaving room for other debuffs."] = "El perjuicio mostrado en el icono central de Perjuicio de banda se excluye de la barra de perjuicios normal, dejando espacio para otros perjuicios."
L["Raid and party frames dim outside range on Wrath, including in combat. Dim Out of Range and Out of Range Alpha control the fade."] = "Los marcos de banda y de grupo se atenúan fuera de alcance en Wrath, también en combate. Atenuar fuera de alcance y Alfa fuera de alcance controlan el desvanecimiento."
L["A large icon in the middle of each frame for important ICC, Ruby Sanctum, Trial of the Crusader, Ulduar and Naxxramas debuffs, highest priority first, with timer, stacks and a dispel colored border. Without a listed debuff it can show a dispellable one instead."] = "Un icono grande en el centro de cada marco para los perjuicios importantes de ICC, el Sagrario Rubí, la Prueba del Cruzado, Ulduar y Naxxramas, primero el de mayor prioridad, con temporizador, acumulaciones y un borde del color de disipación. Sin un perjuicio de la lista puede mostrar uno disipable en su lugar."
L["Dispel Overlay styles with opacity, a dispel colored Frame Border, Type Icon Position, per-type Dispel Colors and Only Show Dispellable."] = "Estilos de Superposición de disipación con opacidad, un Borde del marco del color de disipación, Posición del icono de tipo, Colores de disipación por tipo y Mostrar solo disipables."
L["Overlay, Real or No Preview. The preview opens while the Raid or Party page is open and closes when you leave it, close the panel or enter combat."] = "Superposición, Real o Sin vista previa. La vista previa se abre mientras la página Banda o Grupo está abierta y se cierra al salir de ella, cerrar el panel o entrar en combate."
L["Enemy casts show as icons on the party or raid member being cast at, with a cast sweep and interruptible border. Party defaults to When Healing; each raid layout has its own mode. Wrath has no spell target, so the victim is the caster's target, and only enemies someone in the group targets are seen"] = "Los lanzamientos enemigos se muestran como iconos en el miembro del grupo o banda al que se dirigen, con un barrido de lanzamiento y un borde de interrumpible. Grupo usa por defecto Al sanar; cada diseño de banda tiene su propio modo. Wrath no tiene objetivo de hechizo, así que la víctima es el objetivo del lanzador, y solo se ven los enemigos que alguien del grupo tiene como objetivo"
L["Damage shields show on the health bar as on Retail: Absorb Style, Opacity, Color, Placement and Show Overshield. Wrath does not report shield amounts, so they are estimated from the combat log"] = "Los escudos de daño se muestran en la barra de vida como en Retail: Estilo de absorción, Opacidad, Color, Ubicación y Mostrar sobreescudo. Wrath no informa de la cantidad de los escudos, así que se estiman a partir del registro de combate"
L["Health Bar Texture lists textures from SharedMedia and other addons, also in the aura indicator preview"] = "Textura de barra de vida muestra texturas de SharedMedia y de otros addons, también en la vista previa de indicadores de aura"
L["25-Player Preview"] = "Vista previa de 25 jugadores"
L["The Unlock Mode and options previews open on the 25-player layout instead of 40"] = "Las vistas previas del Modo desbloqueo y de las opciones se abren con el diseño de 25 jugadores en lugar del de 40"
L["Health color modes, backgrounds, threat, target and hover borders, text and icon placement"] = "Modos de color de vida, fondos, amenaza, bordes de objetivo y al pasar el ratón, y ubicación de textos e iconos"
L["Incoming heals and resurrections from players who use a HealComm addon"] = "Sanaciones entrantes y resurrecciones de jugadores que usan un addon HealComm"
L["Main Tank, Pet and Friendly Boss frames plus Healer Mana text, each with an Unlock Mode mover"] = "Marcos de tanque principal, de mascota y de jefe amistoso más el texto de maná de sanadores, cada uno con un movedor del Modo desbloqueo"
L["The Party page has a LAYOUT section with Horizontal Frames"] = "La página Grupo tiene una sección DISEÑO con Marcos horizontales"
L["Ready check icons show a green check for players who accepted and for the one who started the check, instead of a red X when the check ended."] = "Los iconos de comprobación de disponibilidad muestran un tic verde para los jugadores que aceptaron y para quien inició la comprobación, en lugar de una X roja al terminar la comprobación."
L["The party leader icon shows on the leader only instead of on several party members."] = "El icono de líder del grupo se muestra solo en el líder en lugar de en varios miembros del grupo."
L["Set Focus and Clear Focus in the raid and party frame menu work out of combat without the 'blocked from an action' popup; in combat they are hidden, use a Click Casting Focus binding there."] = "Establecer foco y Quitar foco en el menú de los marcos de banda y grupo funcionan fuera de combate sin la ventana de 'acción bloqueada'; en combate se ocultan, usa allí una asignación de foco de Click Casting."
L["Ready check icons show on raid and party frames again."] = "Los iconos de comprobación de disponibilidad vuelven a mostrarse en los marcos de banda y grupo."
L["Hide Sated / Exhaustion also hides the 81005 Bloodlust lockout debuff."] = "Ocultar Saciado / Agotamiento también oculta el perjuicio de bloqueo de Ansia de sangre 81005."
L["Pet frames no longer throw a SecureTemplates strupper error when they first appear."] = "Los marcos de mascota ya no provocan un error de strupper de SecureTemplates al aparecer por primera vez."
L["The Buffs/Debuffs editor's Add New menu no longer closes on the first click."] = "El menú Añadir nuevo del editor de Beneficios/Perjuicios ya no se cierra al primer clic."
L["Element Options for raid and party frames now open the matching settings."] = "Opciones de elementos para los marcos de banda y grupo ahora abre los ajustes correspondientes."
L["Profile strings exported from Retail EllesmereUI import everything this client supports: each module keeps its current settings and takes the Retail values it understands. Retail-only modules, spec setups and Cooldown Manager spells are skipped, and chat reports how many settings came in."] = "Las cadenas de perfil exportadas desde EllesmereUI de Retail importan todo lo que este cliente admite: cada módulo conserva sus ajustes actuales y toma los valores de Retail que entiende. Se omiten los módulos exclusivos de Retail, las configuraciones por especialización y los hechizos del Gestor de reutilización, y el chat indica cuántos ajustes se importaron."
L["A button on Global Settings puts back the game settings EUI changed (nameplate, minimap, chat and tooltip options, chat font sizes and keys Quickdraw took), then turns EUI off for this character and reloads. Your profiles are kept."] = "Un botón en Ajustes globales restaura los ajustes del juego que EUI cambió (opciones de placas de nombre, minimapa, chat y descripciones, tamaños de fuente del chat y teclas que tomó Quickdraw), luego desactiva EUI para este personaje y recarga. Tus perfiles se conservan."
L["A drawn cooldown sweep for modules that want round or colored swipes; the Wrath client's own swipe is always a dark square. Cooldown Manager uses it first."] = "Un barrido de reutilización dibujado para los módulos que quieren barridos redondos o de color; el barrido propio del cliente de Wrath siempre es un cuadrado oscuro. El Gestor de reutilización lo usa primero."
L["When a guild or group member runs a newer EllesmereUI release, chat tells you once per session. Type /euiupdate for the download link. Wrath has no internet access, so the news comes from other EUI users."] = "Cuando un miembro de la hermandad o del grupo usa una versión más reciente de EllesmereUI, el chat te avisa una vez por sesión. Escribe /euiupdate para obtener el enlace de descarga. Wrath no tiene acceso a internet, así que el aviso llega de otros usuarios de EUI."
L["The Locales addon provides community translations for all original Wrath client languages, with English fallback and Lua 5.1 formatting."] = "El addon Locales ofrece traducciones de la comunidad para todos los idiomas originales del cliente de Wrath, con inglés como respaldo y formato de Lua 5.1."
L["The collapsed menu displays the original Ellesmere E logo with the UI accent color and a working close icon on the Wrath client."] = "El menú contraído muestra el logotipo E original de Ellesmere con el color de acento de la interfaz y un icono de cierre funcional en el cliente de Wrath."
L["Fonts, bar textures and sounds that other addons register with LibSharedMedia appear in the EllesmereUI menus, including ones registered after login."] = "Las fuentes, texturas de barra y sonidos que otros addons registran con LibSharedMedia aparecen en los menús de EllesmereUI, incluidos los registrados después de iniciar sesión."
L["A shared outline picker for individual texts: None, Outline, Thick Outline or Shadow, with Module Default following the Fonts page. Text keeps its color when you switch."] = "Un selector de contorno compartido para textos individuales: Ninguno, Contorno, Contorno grueso o Sombras, con Predeterminado del módulo siguiendo la página Fuentes. El texto mantiene su color al cambiar."
L["The Incompatible Addon popup can disable the other addon or the affected EllesmereUI module and reload. Okay and Don't show again work as before."] = "La ventana de Addon incompatible puede desactivar el otro addon o el módulo de EllesmereUI afectado y recargar. Aceptar y No volver a mostrar funcionan como antes."
L["Per-spec setting groups with automatic capture and their own Unlock Mode layouts, plus conditional overrides for dungeons, raids, arenas, battlegrounds, solo play and out of combat."] = "Grupos de ajustes por especialización con captura automática y sus propios diseños del Modo desbloqueo, además de anulaciones condicionales para mazmorras, bandas, arenas, campos de batalla, juego en solitario y fuera de combate."
L["The Esc menu has EllesmereUI and EUI Unlock Mode buttons, shown by default. Both follow the EUI Buttons setting in Global Settings."] = "El menú de Esc tiene botones de EllesmereUI y Modo de desbloqueo de EUI, visibles por defecto. Ambos siguen el ajuste Botones EUI de Ajustes globales."
L["With Show Spell ID on Tooltip on, item tooltips add the item ID and icon file name. Each line has its own toggle"] = "Con Mostrar ID de hechizo en el tooltip activado, las descripciones de objetos añaden el ID del objeto y el nombre del archivo del icono. Cada línea tiene su propia opción"
L["Raid and Unit Frames read absorb shields from a shared estimate: rank base value plus your own spell power, minus what each shield absorbs in the combat log. Clients with a native absorb API use it directly"] = "Los Marcos de banda y de unidad leen los escudos de absorción de una estimación compartida: valor base del rango más tu propio poder con hechizos, menos lo que absorbe cada escudo en el registro de combate. Los clientes con una API de absorción nativa la usan directamente"
L["Arena Frames joins the sidebar, first-use list, profiles, spec overrides, module fonts and search"] = "Marcos de arena se une a la barra lateral, la lista de primer uso, los perfiles, las anulaciones por especialización, las fuentes de módulo y la búsqueda"
L["Profile strings and shared exports work again"] = "Las cadenas de perfil y las exportaciones compartidas vuelven a funcionar"
L["An ice blue options theme; Match Accent to Theme follows each theme's palette"] = "Un tema de opciones azul hielo; Ajustar acento al tema sigue la paleta de cada tema"
L["Lights, beams, music and spin on boss kills, arena and battleground wins, Bloodlust/Heroism and level ups"] = "Luces, rayos, música y giros al derrotar jefes, al ganar arenas y campos de batalla, con Ansia de sangre/Heroísmo y al subir de nivel"
L["Show Spell ID on Tooltip covers spells, action buttons, auras and chat links (off by default)"] = "Mostrar ID de hechizo en el tooltip abarca hechizos, botones de acción, auras y enlaces de chat (desactivado por defecto)"
L["The options sidebar shows the combined memory used by all loaded EllesmereUI addons"] = "La barra lateral de opciones muestra la memoria combinada usada por todos los addons de EllesmereUI cargados"
L["The sidebar sync button opens its profile list again instead of erroring when you have more than one profile."] = "El botón de sincronización de la barra lateral vuelve a abrir su lista de perfiles en lugar de dar error cuando tienes más de un perfil."
L["Retail profile strings bring their element positions: action, XP and menu bars, CDM bars, raid and party frames, chat, damage meter windows, QoL displays, resource bars and the fixed tooltip land where the creator placed them."] = "Las cadenas de perfil de Retail traen las posiciones de sus elementos: barras de acción, de PX y de menú, barras de CDM, marcos de banda y grupo, chat, ventanas del medidor de daño, pantallas de Calidad de vida, barras de recursos y la descripción fija quedan donde las colocó su creador."
L["Nameplates-only Retail profile strings are recognised as Retail; bar width and height, cast bar height and color, name size and aura sizes carry over."] = "Las cadenas de perfil de Retail solo de placas de nombre se reconocen como de Retail; se transfieren el ancho y alto de la barra, el alto y color de la barra de lanzamiento, el tamaño del nombre y los tamaños de las auras."
L["Unlock Mode: the top bar toggle icons and labels are brighter, so they no longer read dark grey on the banner."] = "Modo desbloqueo: los iconos y etiquetas de los interruptores de la barra superior son más brillantes, así que ya no se ven gris oscuro sobre el letrero."
L["Set Focus and Clear Focus in right-click menus from EUI frames go through a secure button out of combat instead of being blocked; in combat they are hidden."] = "Establecer foco y Quitar foco en los menús de clic derecho de los marcos de EUI pasan por un botón seguro fuera de combate en lugar de quedar bloqueados; en combate se ocultan."
L["Unlock Mode: the arrow keys move the selected element 1 pixel again (hold Shift for 100)."] = "Modo desbloqueo: las flechas vuelven a mover el elemento seleccionado 1 píxel (mantén Shift para 100)."
L["Works alongside !!!ClassicAPI: its clipping and mask functions are no longer used on EUI frames, so animated glows and the options panel stop erroring."] = "Funciona junto a !!!ClassicAPI: sus funciones de recorte y máscara ya no se usan en los marcos de EUI, así que los resplandores animados y el panel de opciones dejan de dar errores."
L["Opening the options no longer errors with \"attempt to index local 'mask'\" on clients where another addon adds an empty mask function."] = "Abrir las opciones ya no da el error \"attempt to index local 'mask'\" en clientes donde otro addon añade una función de máscara vacía."
L["The profile Import and Export boxes no longer error with \"attempt to call method 'GetNumLines'\" and scroll to fit long strings."] = "Los cuadros de Importar y Exportar perfil ya no dan el error \"attempt to call method 'GetNumLines'\" y se desplazan para ajustarse a cadenas largas."
L["The collapsed menu shows the Ellesmere E logo again instead of a plain black circle."] = "El menú contraído vuelve a mostrar el logotipo E de Ellesmere en lugar de un círculo negro liso."
L["Action button tooltips show the real spell ID instead of the spellbook slot."] = "Las descripciones de los botones de acción muestran el ID de hechizo real en lugar de la casilla del libro de hechizos."
L["Fixed an \"attempt to call global 'issecretvalue'\" error from Cooldown Manager glows before the options panel was first opened."] = "Corregido un error \"attempt to call global 'issecretvalue'\" de los resplandores del Gestor de reutilización antes de abrir por primera vez el panel de opciones."
L["Unlock Mode widget tooltips use Wrath-compatible alpha fades, fixing the SetFromAlpha error on Grow Right."] = "Las descripciones de los widgets del Modo desbloqueo usan desvanecimientos de alfa compatibles con Wrath, lo que corrige el error de SetFromAlpha en Crecer a la derecha."
L["The options search results list has a fully opaque background with its results drawn above it, so sidebar and page text no longer bleeds into the results."] = "La lista de resultados de búsqueda de las opciones tiene un fondo totalmente opaco con los resultados dibujados encima, así que el texto de la barra lateral y de la página ya no se transparenta en los resultados."
L["Unlock Mode no longer errors on SetMaxLines when it first opens, so element movers appear again."] = "El Modo desbloqueo ya no da error en SetMaxLines al abrirse por primera vez, así que los movedores de elementos vuelven a aparecer."
L["The Patch Notes reminder dot now lights after each backport update."] = "El punto de aviso de Notas del parche ahora se enciende tras cada actualización del backport."
L["The options search results now draw above the sidebar and page instead of behind them."] = "Los resultados de búsqueda de las opciones ahora se dibujan sobre la barra lateral y la página en lugar de detrás."
L["The Unlock Mode right-click menu no longer closes right after opening when many elements are on screen."] = "El menú de clic derecho del Modo desbloqueo ya no se cierra justo después de abrirse cuando hay muchos elementos en pantalla."
L["Opening the Raid Frames options no longer causes a stack overflow in Settings Overrides."] = "Abrir las opciones de Marcos de banda ya no provoca un desbordamiento de pila en Ajustes específicos."
L["Unlock Mode art, options page icons and the Unlock Mode top bar are now visible and readable."] = "El arte del Modo desbloqueo, los iconos de las páginas de opciones y la barra superior del Modo desbloqueo ahora son visibles y legibles."
L["The addon list shows clean module names, grouped under EllesmereUI in addon managers."] = "La lista de addons muestra nombres de módulo limpios, agrupados bajo EllesmereUI en los gestores de addons."
L["Search Features and Search Module Settings accept typing again."] = "Buscar funciones y Buscar ajustes de módulo vuelven a aceptar texto."
L["Clients whose atlas lookup errors on unknown names (such as custom 3.3.5 clients with Retail UI ports) no longer stop EllesmereUI files from loading."] = "Los clientes cuya búsqueda de atlas da error con nombres desconocidos (como clientes 3.3.5 personalizados con ports de la interfaz de Retail) ya no impiden que se carguen los archivos de EllesmereUI."
L["Like Retail 9.4, the DataBars page opens with a bar selector at the top: rename or delete a bar right in its menu, or pick + Create New DataBar. + New Bar shows the four starter templates as cards, and with no bars yet the page shows them as a card grid."] = "Como en Retail 9.4, la página DataBars se abre con un selector de barra arriba: renombra o borra una barra desde su propio menú, o elige + Crear nueva DataBar. + Nueva barra muestra las cuatro plantillas iniciales como tarjetas, y sin barras todavía la página las muestra como una cuadrícula de tarjetas."
L["Like Retail 9.4, the options window has a Window Scale slider in its top corner that resizes it in smooth 5% steps; the mouse wheel over it, or Shift + mouse wheel anywhere on the window, works too. The credit to Ellesmere now sits under the close button."] = "Como en Retail 9.4, la ventana de opciones tiene un control deslizante de Escala de la ventana en su esquina superior que la redimensiona en pasos suaves del 5%; también funciona la rueda del ratón sobre él, o Shift + rueda del ratón en cualquier parte de la ventana. El crédito a Ellesmere ahora está bajo el botón de cerrar."
L["Global Settings opens with Reset ALL EUI Addon Settings and Uninstall EUI side by side, like Retail 9.4. Reset ALL now asks you to type Confirm. Optimize My FPS and Graphics is gone: the graphics settings it changed do not exist on this client."] = "Ajustes globales se abre con Restablecer TODOS los ajustes de EUI y Desinstalar EUI uno al lado del otro, como en Retail 9.4. Restablecer TODO ahora te pide escribir Confirm. Optimizar mis FPS y gráficos ya no está: los ajustes gráficos que cambiaba no existen en este cliente."
L["Like Retail 9.4, each look card on the Style page has a menu of the modules using it: tick modules under another look, then press Apply Styles to switch them all with one reload. The menus list only looks this client can draw: Cooldown Manager, Minimap and Damage Meters offer EllesmereUI and Classic WoW UI, Player Aura Bars is gone, and Apply to All skips modules without that look."] = "Como en Retail 9.4, cada tarjeta de aspecto de la página Estilo tiene un menú con los módulos que lo usan: marca módulos que estén en otro aspecto y pulsa Aplicar estilos para cambiarlos todos con una sola recarga. Los menús solo muestran los aspectos que este cliente puede dibujar: Gestor de reutilización, Minimapa y Medidor de daño ofrecen EllesmereUI e Interfaz de WoW clásico, Barras de auras del jugador ya no está, y Aplicar a todo omite los módulos sin ese aspecto."
L["The import page can update your current profile instead of making a new one: tick Import into current profile and the string's selected modules (for example only Nameplates) replace their settings there while the rest of the profile stays."] = "La página de importación puede actualizar tu perfil actual en lugar de crear uno nuevo: marca Importar en el perfil actual y los módulos seleccionados de la cadena (por ejemplo, solo Placas de nombre) sustituyen allí sus ajustes mientras el resto del perfil se mantiene."
L["The EUI Staff page opens with thanks to Ellesmere and the port staff card with a GitHub link to the releases. The header line crediting Ellesmere opens it."] = "La página EUI Staff se abre con un agradecimiento a Ellesmere y la tarjeta del equipo del port con un enlace de GitHub a las versiones. La línea del encabezado que acredita a Ellesmere la abre."
L["Custom spell reminders, visibility and sounds are saved separately for each character, independently of shared profiles."] = "Los recordatorios de hechizos personalizados, la visibilidad y los sonidos se guardan por separado para cada personaje, independientemente de los perfiles compartidos."
L["Optional achievement, trade and guild recruitment filters, plus your own blocked words and phrases."] = "Filtros opcionales de logros, comercio y reclutamiento de hermandad, además de tus propias palabras y frases bloqueadas."
L["Configure repeat timing, sender matching and chat scopes from the new Spam Filter page."] = "Configura el tiempo de repetición, la coincidencia de remitente y los ámbitos de chat en la nueva página Filtro de spam."
L["Outline menus in the Nameplates and Unit Frames text cogs, and Zone Text Outline in Quality of Life. The Unit Frames preview shows each text's outline."] = "Menús de contorno en los engranajes de texto de Placas de nombre y Marcos de unidad, y Contorno del texto de zona en Calidad de vida. La vista previa de Marcos de unidad muestra el contorno de cada texto."
L["New PETS and DIMINISHING RETURNS sections, plus Fade Out of Range and its opacity under Target and Visibility."] = "Nuevas secciones MASCOTAS y RENDIMIENTOS DECRECIENTES, además de Desvanecer fuera de alcance y su opacidad en Objetivo y visibilidad."
L["Announce Interrupts and Accept Invites from Friends & Guild in the GROUP section, and a Disband Group button on Raid Tools."] = "Anunciar interrupciones y Aceptar invitaciones de amigos y hermandad en la sección GRUPO, y un botón Disolver grupo en Herramientas de banda."
L["Bar Display, Menu, Bags & XP Bars and Bar Animations, with a live preview of the selected bar. Click an icon, keybind or count to jump to its setting."] = "Visualización de barra, Menú, Bolsas y barras de PX y Animaciones de barra, con una vista previa en vivo de la barra seleccionada. Haz clic en un icono, atajo o cantidad para saltar a su ajuste."
L["The Raid and Party pages gain the Retail DISPELS section and a Preview Mode (Real, Overlay or No Preview) at the top."] = "Las páginas Banda y Grupo obtienen la sección DISIPACIONES de Retail y un Modo de vista previa (Real, Superposición o Sin vista previa) arriba."
L["Party and Raid pages gain a TARGETED SPELLS section: mode, preview, icon size, maximum icons, position, growth, offsets, cast swipe, cast timer and interruptible colors."] = "Las páginas Grupo y Banda obtienen una sección HECHIZOS DIRIGIDOS: modo, vista previa, tamaño de icono, máximo de iconos, posición, crecimiento, desplazamientos, barrido de lanzamiento, temporizador de lanzamiento y colores de interrumpible."
L["Raid Frames (Party and Raid) and Unit Frames (player, target, focus) gain an ABSORBS section for the estimated shields, with a shield in the Unit Frames preview."] = "Marcos de banda (Grupo y Banda) y Marcos de unidad (jugador, objetivo, foco) obtienen una sección ABSORCIONES para los escudos estimados, con un escudo en la vista previa de Marcos de unidad."
L["CDM Bars now opens with Retail's bar dropdown (rename or delete custom bars, add Cooldowns, Utility, Buff or FocusKick bars) and the selected bar's icons: drag to reorder, click an icon to edit it, middle-click to remove it, and use + to add spells or buffs."] = "Barras de CDM ahora se abre con el desplegable de barras de Retail (renombra o borra barras personalizadas, añade barras de Reutilizaciones, Utilidad, Beneficios o FocusKick) y los iconos de la barra seleccionada: arrastra para reordenar, haz clic en un icono para editarlo, clic central para quitarlo, y usa + para añadir hechizos o beneficios."
L["Hide server announcements such as \"Name the level 11 Gnome Warrior has been slain by ... in Westfall\", optionally keeping deaths from a chosen level up visible."] = "Oculta los anuncios del servidor como \"Nombre, el Guerrero gnomo de nivel 11, ha sido asesinado por ... en Páramos de Poniente\", con la opción de mantener visibles las muertes a partir de un nivel elegido."
L["The FocusKick Cast Sound and the Chat sounds list EllesmereUI and SharedMedia sounds, and the Textures page links Damage Meters to its per-window Bar Texture"] = "El sonido de lanzamiento de FocusKick y los sonidos del chat muestran sonidos de EllesmereUI y SharedMedia, y la página Texturas enlaza el Medidor de daño con su Textura de barra por ventana"
L["New dropdown at the top of Icons, with a link to apply it to every bar. The preview shows the shape."] = "Nuevo desplegable arriba en Iconos, con un enlace para aplicarlo a todas las barras. La vista previa muestra la forma."
L["Boss Debuff Icon, Icon Size, Icon Offset Y and Show Dispellable When No Boss Debuff under Dispels"] = "Icono de perjuicio de jefe, Tamaño del icono, Desplazamiento Y del icono y Mostrar disipables si no hay perjuicio de jefe en Disipaciones"
L["General, Layout, Health and Power, Text, Icons, Cast Bar and Target and Visibility sections"] = "Secciones General, Diseño, Vida y recurso, Texto, Iconos, Barra de lanzamiento y Objetivo y visibilidad"
L["Display, Extras and Wrath Inventory settings, including Delete Saved Character"] = "Ajustes de Visualización, Extras e Inventario de Wrath, incluido Borrar personaje guardado"
L["Class icon themes, class colored names, borders, accent colors, faction banners and invite auto-accept"] = "Temas de iconos de clase, nombres con color de clase, bordes, colores de acento, estandartes de facción y aceptación automática de invitaciones"
L["Display, Colors, General and Aura Filters with inline color swatches and cog menus"] = "Visualización, Colores, General y Filtros de auras con muestras de color integradas y menús de engranaje"
L["Quick Loot, Auto-Fill Delete Confirmation, Auto Repair and Auto Sell Junk in the Retail layout"] = "Despojo rápido, Rellenar confirmación de eliminación automáticamente, Reparación automática y Vender chatarra automáticamente con el diseño de Retail"
L["Display, Colors and Extras sections with inline swatches and auto accept and turn-in cogs"] = "Secciones Visualización, Colores y Extras con muestras integradas y engranajes de aceptación y entrega automáticas"
L["Wrath spell icons, real cast times and the same faction and portrait art as the live frames"] = "Iconos de hechizos de Wrath, tiempos de lanzamiento reales y el mismo arte de facción y retrato que los marcos reales"
L["The Active Profile dropdown shows the rename, delete and keybind icons on each profile again."] = "El desplegable Perfil activo vuelve a mostrar los iconos de renombrar, borrar y atajo en cada perfil."
L["Dropdowns open again with !!!ClassicAPI installed; its clipping function no longer moves the menus into an empty scroll frame."] = "Los desplegables vuelven a abrirse con !!!ClassicAPI instalado; su función de recorte ya no mueve los menús a un marco de desplazamiento vacío."
L["Resetting Global Settings no longer stops partway with an error and reloads the UI again."] = "Restablecer los Ajustes globales ya no se detiene a medias con un error ni vuelve a recargar la interfaz."
L["Options that do nothing on the Wrath client are hidden: image sharpening, Lag Tolerance, Combat Text Size, Swiftmend dim, Slug outline, class resource dark mode and colors, Retail-only class and power colors, and cursor ring textures."] = "Las opciones que no hacen nada en el cliente de Wrath están ocultas: nitidez de imagen, Tolerancia de latencia, Tamaño del texto de combate, atenuación de Alivio presto, contorno Slug, modo oscuro y colores de recursos de clase, colores de clase y de recurso exclusivos de Retail, y texturas del anillo del cursor."
L["Global Settings no longer shows the Gamepad page, which has nothing to control on the Wrath client."] = "Ajustes globales ya no muestra la página Mando, que no tiene nada que controlar en el cliente de Wrath."
L["Max Camera Distance saves and keeps its value instead of resetting to 1.0, and goes up to 4 like the Wrath client allows."] = "Distancia máxima de cámara guarda y mantiene su valor en lugar de volver a 1.0, y llega hasta 4 como permite el cliente de Wrath."
L["CDM Bars and Tracking Bars open without an \"attempt to call field 'disabled'\" error, and nine toggles show their tooltips again."] = "Barras de CDM y Barras de seguimiento se abren sin el error \"attempt to call field 'disabled'\", y nueve interruptores vuelven a mostrar sus descripciones."
L["Chat > Spam Filter: the chat type settings stay usable when only the trade or recruitment filter is on, and the tooltips explain what each one covers."] = "Chat > Filtro de spam: los ajustes de tipo de chat siguen siendo usables cuando solo está activo el filtro de comercio o de reclutamiento, y las descripciones explican qué abarca cada uno."
L["Opening the options no longer makes later Blizzard actions risk being blocked in EllesmereUI's name."] = "Abrir las opciones ya no hace que acciones posteriores de Blizzard corran el riesgo de quedar bloqueadas en nombre de EllesmereUI."
L["Checklist menus such as Visibility tick and untick their boxes as soon as they are clicked, even when the module's live update runs into a problem, instead of only after closing and reopening the menu."] = "Los menús de lista de verificación como Visibilidad marcan y desmarcan sus casillas en cuanto se hace clic, incluso cuando la actualización en vivo del módulo encuentra un problema, en lugar de solo tras cerrar y volver a abrir el menú."
L["Dropdown lists, checklists and other option popups draw their items above their own background, on a solid background, instead of showing faded items with the page bleeding through."] = "Las listas desplegables, listas de verificación y otras ventanas de opciones dibujan sus elementos sobre su propio fondo, sobre un fondo sólido, en lugar de mostrar elementos desvaídos con la página transparentándose."
L["The Style page now keeps the Unit Frames health colors per look, so switching between Classic WoW UI and the EllesmereUI look keeps each one's colors."] = "La página Estilo ahora guarda los colores de vida de los Marcos de unidad por aspecto, así que al cambiar entre Interfaz de WoW clásico y el aspecto EllesmereUI cada uno conserva sus colores."
L["The Unit Frames preview and power color swatches show the original game power colors under Classic WoW UI."] = "La vista previa de Marcos de unidad y las muestras de color de recurso muestran los colores de recurso originales del juego con Interfaz de WoW clásico."
L["Each Core Text Position row, Spell Name, Cast Timer and Friendly Names now has its own gear for the outline instead of hiding it in the size popup."] = "Cada fila de Posiciones de textos principales, Nombre de hechizo, Temporizador de lanzamiento y Nombres amistosos tiene ahora su propio engranaje para el contorno en lugar de esconderlo en la ventana de tamaño."
L["Pressing Esc to close Blizzard windows no longer shows \"EllesmereUIOptions has been blocked from an action\"."] = "Pulsar Esc para cerrar ventanas de Blizzard ya no muestra \"EllesmereUIOptions has been blocked from an action\"."
L["Combat damage, healing, periodic and pet damage toggles use Wrath's own combat text settings."] = "Los interruptores de daño de combate, sanación, periódicos y daño de mascota usan los ajustes de texto de combate propios de Wrath."
L["Hidden option widgets no longer take keyboard focus after other windows close with Escape."] = "Los widgets de opciones ocultos ya no toman el foco del teclado después de que otras ventanas se cierren con Escape."
L["Dragging or typing in a slider no longer errors."] = "Arrastrar o escribir en un control deslizante ya no da error."
L["The settings panel opens on clients whose atlas lookup errors on unknown names, instead of failing with an 'NS' error."] = "El panel de ajustes se abre en clientes cuya búsqueda de atlas da error con nombres desconocidos, en lugar de fallar con un error 'NS'."
L["Displays has a ZONE TEXT section with Move Zone Text."] = "Pantallas tiene una sección TEXTO DE ZONA con Mover texto de zona."
L["Raid Tools no longer has a BOSS MOD BARS section: AbilityTimeline's Sources options hide DBM and BigWigs bars."] = "Herramientas de banda ya no tiene una sección BARRAS DE BOSS MODS: las opciones de Fuentes de AbilityTimeline ocultan las barras de DBM y BigWigs."
L["The Retail raid panel: show it never, in raids, in any group or always, as a resizable Compact Band, one or two windows, or only one part. It can start as a small icon, opens and closes with a keybind even in combat, and has three pull timers, Convert and Disband. Reinvite removes everyone and invites them back to the same kind of group, and Convert to Party rebuilds a raid of five or fewer as a party the same way. Shift + Left Click a marker to place its world marker when the marker item is in your bags, or Shift + Left Click the clear icon to reset world markers. In a raid it only shows for the leader and assistants."] = "El panel de banda de Retail: muéstralo nunca, en bandas, en cualquier grupo o siempre, como una Banda compacta redimensionable, una o dos ventanas, o solo una parte. Puede empezar como un icono pequeño, se abre y se cierra con un atajo incluso en combate, y tiene tres temporizadores de pull, Convertir y Disolver. Reinvitar expulsa a todos y los vuelve a invitar al mismo tipo de grupo, y Convertir en grupo reconstruye del mismo modo una banda de cinco o menos como grupo. Shift + Clic izquierdo en un marcador coloca su marcador de mundo cuando el objeto del marcador está en tus bolsas, o Shift + Clic izquierdo en el icono de borrar restablece los marcadores de mundo. En una banda solo se muestra al líder y a los ayudantes."
L["One key casts Misdirection or Tricks of the Trade on your focus, the tank (typed name, Main Tank or tank role), your friendly target or your pet. An icon shows who it will go to, the buff timer and the cooldown. Bind it in Key Bindings."] = "Una tecla lanza Redirección o Secretos del oficio sobre tu foco, el tanque (nombre escrito, tanque principal o rol de tanque), tu objetivo amistoso o tu mascota. Un icono muestra a quién irá, el temporizador del beneficio y la reutilización. Asígnalo en Asignación de teclas."
L["Damage taken, healing, avoids and entering or leaving combat scroll above the player frame instead of Blizzard's combat text, with Straight, Fountain or Static animations, colors per type and a mover in Unlock Mode."] = "El daño recibido, la sanación, las evitaciones y la entrada o salida de combate se desplazan sobre el marco del jugador en lugar del texto de combate de Blizzard, con animaciones Recto, Surtidor o Estático, colores por tipo y un movedor en el Modo desbloqueo."
L["Picks an NPC's only dialog option for you. Hold Shift to skip it; instances and NPCs with quests to take or turn in are left alone. Its cog can also skip past low level quests."] = "Elige por ti la única opción de diálogo de un PNJ. Mantén Shift para omitirlo; las estancias y los PNJ con misiones para aceptar o entregar no se tocan. Su engranaje también puede saltarse las misiones de nivel bajo."
L["An arrow next to the To box lists your alts on this realm and faction, guild members and the last names you mailed. Click a name to fill it in."] = "Una flecha junto al cuadro Para muestra tus alters de este reino y facción, los miembros de la hermandad y los últimos nombres a los que enviaste correo. Haz clic en un nombre para rellenarlo."
L["Pick None, Outline, Thick Outline or Shadow for the zone, sub-zone and PvP text shown when entering an area. Blizzard Default keeps the game's own font."] = "Elige Ninguno, Contorno, Contorno grueso o Sombras para el texto de zona, subzona y JcJ que se muestra al entrar en un área. Predeterminado de Blizzard mantiene la fuente propia del juego."
L["Posts the spell you or your pet interrupted, with a spell link, to Say, Emote, Party or Raid. Party and Raid switch to the battleground channel inside battlegrounds."] = "Publica el hechizo que tú o tu mascota interrumpisteis, con un enlace al hechizo, en Decir, Emoción, Grupo o Banda. Grupo y Banda cambian al canal de campo de batalla dentro de los campos de batalla."
L["Group invites from your friends list and guildmates are accepted automatically, unless you are already grouped or queued in the Dungeon Finder."] = "Las invitaciones de grupo de tu lista de amigos y de compañeros de hermandad se aceptan automáticamente, salvo que ya estés en grupo o en cola en el Buscador de mazmorras."
L["A Disband button on Raid Tools removes everyone from your raid or party after a confirmation. Leader only, never in combat."] = "Un botón Disolver en Herramientas de banda expulsa a todos de tu banda o grupo tras una confirmación. Solo para el líder, nunca en combate."
L["Loots everything instantly even with Blizzard's Auto Loot off; hold Shift to see the loot window. Locked slots such as group rolls and master loot are skipped."] = "Despoja todo al instante incluso con el Despojo automático de Blizzard desactivado; mantén Shift para ver la ventana de botín. Se omiten las casillas bloqueadas, como las tiradas de grupo y el maestro despojador."
L["FPS and latency, secondary stats, durability warning, combat and death alerts, a crosshair and a new target distance text, all movable in Unlock Mode."] = "FPS y latencia, estadísticas secundarias, aviso de durabilidad, alertas de combate y muerte, un punto de mira y un nuevo texto de distancia al objetivo, todo movible en el Modo desbloqueo."
L["The FPS counter's new default Text Color, Quality, turns FPS and each latency value green, yellow or red (60/30 fps, 100/250 ms). Custom and Class Color remain available."] = "El nuevo Color del texto predeterminado del contador de FPS, Calidad, pone los FPS y cada valor de latencia en verde, amarillo o rojo (60/30 fps, 100/250 ms). Personalizado y Color de clase siguen disponibles."
L["Alert sounds from SharedMedia packs that load after Quality of Life play too"] = "También suenan los sonidos de alerta de paquetes de SharedMedia que se cargan después de Calidad de vida"
L["An Open All button takes items and gold one letter at a time, skipping COD and GM mail"] = "Un botón Abrir todo recoge objetos y oro carta a carta, omitiendo el correo contra reembolso y de MJ"
L["With Send Mail open, Shift-click a bag item to attach it and matching items"] = "Con Enviar correo abierto, Shift + clic en un objeto de la bolsa lo adjunta junto con los objetos coincidentes"
L["Opens lootable containers one at a time out of combat (off by default)"] = "Abre los contenedores despojables de uno en uno fuera de combate (desactivado por defecto)"
L["A Train All button beside Train shows how many spells are available and the total cost"] = "Un botón Entrenar todo junto a Entrenar muestra cuántos hechizos hay disponibles y el coste total"
L["Pull timer length, DBM/BigWigs broadcast and a chat countdown"] = "Duración del temporizador de pull, difusión a DBM/BigWigs y una cuenta atrás en el chat"
L["Raid Tools keeps its size after importing a Retail profile."] = "Herramientas de banda mantiene su tamaño tras importar un perfil de Retail."
L["Shift-click mail attach no longer replaces the bag item click handler, so bag clicks stay free of taint."] = "Adjuntar correo con Shift + clic ya no sustituye el controlador de clics de los objetos de la bolsa, así que los clics en las bolsas quedan libres de contaminación."
L["Hiding DBM and BigWigs bars while AbilityTimeline is active moved to AbilityTimeline itself, as on Retail: Hide DBM bars and Hide BigWigs bars on its Sources page. The Raid Tools option is gone."] = "Ocultar las barras de DBM y BigWigs mientras AbilityTimeline está activo pasó al propio AbilityTimeline, como en Retail: Hide DBM bars y Hide BigWigs bars en su página Sources. La opción de Herramientas de banda ya no está."
L["Logging out, exiting, releasing spirit and other Blizzard confirmation popups no longer trigger the \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\" message."] = "Cerrar sesión, salir del juego, liberar el espíritu y otras ventanas de confirmación de Blizzard ya no provocan el mensaje \"EllesmereUIQoL has been blocked from an action only available to the Blizzard UI\"."
L["The zone name no longer appears in the middle of the screen at small UI scales. It now sits fixed at the top (X 9 / Y 322 from screen center), with no Unlock Mode mover."] = "El nombre de la zona ya no aparece en el centro de la pantalla con escalas de interfaz pequeñas. Ahora queda fijo arriba (X 9 / Y 322 desde el centro de la pantalla), sin movedor del Modo desbloqueo."
L["Show Player Buffs puts the hovered player's buffs as icons beside the tooltip, with position, size, icons per row and offsets."] = "Mostrar beneficios del jugador pone los beneficios del jugador señalado como iconos junto a la descripción, con posición, tamaño, iconos por fila y desplazamientos."
L["Hovering a stat in the character sheet sidebar glows the equipped items that give it."] = "Al pasar el ratón sobre una estadística de la barra lateral de la hoja de personaje, brillan los objetos equipados que la otorgan."
L["Inspect Enchants and Missing Enhancements"] = "Encantamientos en inspección y mejoras faltantes"
L["Inspect enchants show as an icon with the name on hover, or as names tinted by item quality, in their own size. At max level, red badges flag missing enchants, empty sockets and a missing belt buckle, as on your character sheet."] = "Los encantamientos en inspección se muestran como un icono con el nombre al pasar el ratón, o como nombres teñidos según la calidad del objeto, con su propio tamaño. Al nivel máximo, unas insignias rojas señalan encantamientos faltantes, ranuras vacías y una hebilla de cinturón faltante, como en tu hoja de personaje."
L["Saving an equipment set rebuilds the native icon picker even when already open, preventing the PaperDollFrame nil comparison error."] = "Guardar un equipamiento reconstruye el selector de iconos nativo aunque ya esté abierto, evitando el error de comparación con nil de PaperDollFrame."
L["Need, Greed, Disenchant and Pass buttons on loot rolls count what the rest of the group picked. Hover a button to see who, in class colors."] = "Los botones Necesidad, Codicia, Desencantar y Pasar de las tiradas de botín cuentan lo que eligió el resto del grupo. Pasa el ratón sobre un botón para ver quién, con colores de clase."
L["Player tooltips show GearScore in the GearScoreLite colors, using its formula when it is loaded. GearScoreLite's own line is kept when its option is on."] = "Las descripciones de jugadores muestran el GearScore con los colores de GearScoreLite, usando su fórmula cuando está cargado. La línea propia de GearScoreLite se mantiene cuando su opción está activa."
L["Enchants and gems on every slot, lowest durability, model rotate, pan and zoom, reorderable stat sections and a socket strip that fills sockets from your bags."] = "Encantamientos y gemas en cada casilla, durabilidad más baja, rotación, desplazamiento y zoom del modelo, secciones de estadísticas reordenables y una franja de ranuras que rellena las ranuras desde tus bolsas."
L["Class colored names and health bar, guild rank, target, item level and a cursor or fixed anchor"] = "Nombres y barra de vida con color de clase, rango de hermandad, objetivo, nivel de objeto y un anclaje al cursor o fijo"
L["Item levels on inspect, docking beside the character window and a merchant list mode"] = "Niveles de objeto al inspeccionar, acoplamiento junto a la ventana de personaje y un modo de lista para el vendedor"
L["Resurrect accept glow and a Dungeon Ready countdown bar"] = "Resplandor al aceptar resurrección y una barra de cuenta atrás de Mazmorra lista"
L["The server's Collections and Wardrobe & Transmog windows join the window skins"] = "Las ventanas de Colecciones y de Guardarropa y transfiguración del servidor se unen a los aspectos de ventanas"
L["Barber Shop, PvP and battlemasters, Arena Registrar, battleground score, minimap and capture bar, Help and GM tickets, GM chat status, breath and fatigue timers, stopwatch, raid pullouts, debug tools and Ace3 config windows"] = "Barbería, JcJ y maestros de batalla, Registrador de arena, puntuación de campo de batalla, minimapa y barra de captura, Ayuda y tickets de MJ, estado del chat de MJ, temporizadores de respiración y fatiga, cronómetro, marcos desplegables de banda, herramientas de depuración y ventanas de configuración de Ace3"
L["Ready checks no longer leave an empty black panel for the leader or after you answer."] = "Las comprobaciones de disponibilidad ya no dejan un panel negro vacío para el líder o después de responder."
L["The character sheet Titles tab lists your known titles again; click one to wear it."] = "La pestaña Títulos de la hoja de personaje vuelve a mostrar tus títulos conocidos; haz clic en uno para llevarlo."
L["The Guild Message Of The Day popup (and other wide text popups) no longer covers its title and buttons with the input box."] = "La ventana del Mensaje del día de la hermandad (y otras ventanas de texto anchas) ya no tapa su título y sus botones con el cuadro de texto."
L["The Achievements window no longer darkens the achievement list behind its border."] = "La ventana de Logros ya no oscurece la lista de logros detrás de su borde."
L["The AddOn List window skin toggle only shows when the client has an AddOn List window."] = "La opción de aspecto de la ventana Lista de addons solo se muestra cuando el cliente tiene una ventana Lista de addons."
L["Send Mail shows the To, Subject and message boxes again, and the typing cursor stays visible in skinned edit boxes."] = "Enviar correo vuelve a mostrar los cuadros Para, Asunto y mensaje, y el cursor de escritura sigue visible en los cuadros de texto con aspecto."
L["The fixed tooltip anchor no longer snaps back to its saved spot while you drag it in Unlock Mode."] = "El anclaje de la descripción fija ya no vuelve a su posición guardada mientras lo arrastras en el Modo desbloqueo."
L["Auction House: panels and tabs added by Auctionator and other auction addons keep their own look and layout, and the footer Close buttons no longer get an \"x\" over their text."] = "Casa de subastas: los paneles y pestañas añadidos por Auctionator y otros addons de subastas mantienen su propio aspecto y diseño, y los botones Cerrar del pie ya no reciben una \"x\" sobre su texto."
L["Talents: the close button and the points footer end at the scroll bar instead of past the window edge."] = "Talentos: el botón de cerrar y el pie de puntos terminan en la barra de desplazamiento en lugar de pasar del borde de la ventana."
L["Window tabs keep their dark background instead of showing through."] = "Las pestañas de las ventanas mantienen su fondo oscuro en lugar de transparentarse."
L["World map: the player arrow, party and raid dots, corpse and quest markers stay on the map art after a map view change during combat, including instance maps."] = "Mapa del mundo: la flecha del jugador, los puntos de grupo y banda, el cadáver y los marcadores de misión permanecen sobre el arte del mapa tras un cambio de vista del mapa en combate, incluidos los mapas de estancias."
L["Native dropdown menus no longer show an empty square at the right of each row."] = "Los menús desplegables nativos ya no muestran un cuadrado vacío a la derecha de cada fila."
L["Dropdown boxes in Blizzard windows, such as the Dungeon Finder type, end at their arrow instead of past the window edge."] = "Los cuadros desplegables de las ventanas de Blizzard, como el tipo del Buscador de mazmorras, terminan en su flecha en lugar de pasar del borde de la ventana."
L["Raid Information: the background covers the whole window, including the title, close button, last row and the Extend Raid Lock and Close buttons."] = "Información de banda: el fondo cubre toda la ventana, incluidos el título, el botón de cerrar, la última fila y los botones Extender bloqueo de banda y Cerrar."
L["The Talents and Glyphs background now ends above the tabs and beside the dual spec tabs."] = "El fondo de Talentos y Glifos ahora termina por encima de las pestañas y junto a las pestañas de especialización doble."
L["The Glyphs tab shows its native parchment background again, aligned with the glyph sockets."] = "La pestaña Glifos vuelve a mostrar su fondo de pergamino nativo, alineado con las ranuras de glifos."
L["Sliders in Blizzard windows, such as the Camera and Mouse options, are back to their normal size."] = "Los controles deslizantes de las ventanas de Blizzard, como las opciones de Cámara y Ratón, vuelven a su tamaño normal."
L["Hide Until Usable and Hide Outside Form/Stance"] = "Ocultar hasta que sea usable y Ocultar fuera de forma/actitud"
L["New Cooldown States: Hide Until Usable shows a spell only while it can be cast and is off cooldown (Overpower, Revenge, Victory Rush, Execute); low resources do not hide it. Hide Outside Form/Stance shows it only in the form or stance it needs. Both can close the gap or keep the place."] = "Nuevos Estados de reutilización: Ocultar hasta que sea usable muestra un hechizo solo mientras se puede lanzar y no está en reutilización (Abrumar, Revancha, Ataque victorioso, Ejecutar); la falta de recursos no lo oculta. Ocultar fuera de forma/actitud lo muestra solo en la forma o actitud que necesita. Ambos pueden cerrar el hueco o mantener la posición."
L["The + menu adds an Empty Slot that keeps a position free on the bar, to group icons."] = "El menú + añade un Hueco vacío que mantiene libre una posición en la barra, para agrupar iconos."
L["Bars can switch to a Shaped swipe that follows round icons and takes a Swipe Color, instead of the client's dark square sweep."] = "Las barras pueden cambiar a un barrido Con forma que sigue los iconos redondos y usa un Color del barrido, en lugar del barrido cuadrado oscuro del cliente."
L["Cooldowns, Utility and Buffs bars plus custom bars and a FocusKick bar, tracked from your spellbook, cooldowns and auras. Lists are saved per talent group."] = "Barras de Reutilizaciones, Utilidad y Beneficios más barras personalizadas y una barra FocusKick, seguidas desde tu libro de hechizos, reutilizaciones y auras. Las listas se guardan por grupo de talentos."
L["Aura or cooldown bars for player, target, focus or pet with textures, gradients, stack ticks and pandemic glow, arranged in groups."] = "Barras de auras o reutilizaciones para jugador, objetivo, foco o mascota con texturas, degradados, marcas de acumulación y resplandor de pandemia, organizadas en grupos."
L["The + buttons above the bar icons open Retail's add menu: custom spell, item or slot, trinkets, racial, potions and your learned spells, or buffs and buff presets from the gold +"] = "Los botones + sobre los iconos de la barra abren el menú de añadir de Retail: hechizo, objeto o casilla personalizados, abalorios, racial, pociones y tus hechizos aprendidos, o beneficios y preajustes de beneficios desde el + dorado"
L["Passive proc trinkets in the trinket slots show their icon and the internal cooldown after each proc, with the proc buff while it lasts"] = "Los abalorios pasivos con proc en las casillas de abalorio muestran su icono y la reutilización interna tras cada proc, con el beneficio del proc mientras dura"
L["Tracking bar textures include SharedMedia, and the FocusKick Cast Sound adds EllesmereUI and SharedMedia sounds to the Blizzard ones"] = "Las texturas de las barras de seguimiento incluyen SharedMedia, y el sonido de lanzamiento de FocusKick añade sonidos de EllesmereUI y SharedMedia a los de Blizzard"
L["Light up EllesmereUI, Blizzard or ElvUI action buttons while an aura is active or missing"] = "Ilumina los botones de acción de EllesmereUI, Blizzard o ElvUI mientras un aura está activa o ausente"
L["Always show, dim, hide on cooldown or when ready, and glow when ready"] = "Mostrar siempre, atenuar, ocultar en reutilización o cuando está listo, y resplandor cuando está listo"
L["Racials, healthstones, Wrath potions and buffs such as Heroism and Bloodlust"] = "Raciales, piedras de salud, pociones de Wrath y beneficios como Heroísmo y Ansia de sangre"
L["Show an entry only when a chosen talent is learned"] = "Muestra una entrada solo cuando se ha aprendido un talento elegido"
L["Utility bar options no longer switch to Buffs after a click, and the Cooldowns bar is no longer replaced by a second Buffs bar."] = "Las opciones de la barra Utilidad ya no cambian a Beneficios tras un clic, y la barra Reutilizaciones ya no se sustituye por una segunda barra Beneficios."
L["Racials show once: the Utility bar no longer lists Arcane Torrent (and other racials with class variants) three times."] = "Las raciales se muestran una vez: la barra Utilidad ya no muestra Torrente Arcano (ni otras raciales con variantes de clase) tres veces."
L["A passive trinket in a trinket slot shows its own icon in the options instead of a question mark."] = "Un abalorio pasivo en una casilla de abalorio muestra su propio icono en las opciones en lugar de un signo de interrogación."
L["Bars saved twice or under another bar's name (two Buffs bars and no Cooldowns) are repaired, so each built-in bar keeps its own icons and options."] = "Las barras guardadas dos veces o con el nombre de otra barra (dos barras Beneficios y ninguna Reutilizaciones) se reparan, así que cada barra integrada conserva sus propios iconos y opciones."
L["Auto Sized and Even Split bars with Retail backgrounds, borders and screen edge snapping, plus per-block margins, alignment, scale and colors."] = "Barras de Tamaño automático y División equitativa con fondos, bordes y ajuste a los bordes de pantalla de Retail, además de márgenes, alineación, escala y colores por bloque."
L["20 Wrath Blocks"] = "20 bloques de Wrath"
L["Clock, FPS, latency, location, gold history, bags, durability, XP and reputation, dual spec, professions, travel, micro menu, currency and more."] = "Reloj, FPS, latencia, ubicación, historial de oro, bolsas, durabilidad, PX y reputación, especialización doble, profesiones, viaje, micromenú, monedas y más."
L["Latency text is green, yellow or red by connection quality by default. A Latency swatch in Text Color switches back to it after picking another color."] = "El texto de latencia es verde, amarillo o rojo según la calidad de la conexión por defecto. Una muestra de Latencia en Color del texto vuelve a ello después de elegir otro color."
L["Column tooltips with clickable rows and secure spell, item and macro lines"] = "Descripciones de columna con filas en las que se puede hacer clic y líneas seguras de hechizos, objetos y macros"
L["Every bar has a mover whose Element Options opens that bar's settings"] = "Cada barra tiene un movedor cuyas Opciones de elementos abren los ajustes de esa barra"
L["Profiles from 0.2 are converted automatically"] = "Los perfiles de la 0.2 se convierten automáticamente"
L["Bars snapped to a screen edge or set to full length start in their place after login instead of needing Unlock Mode opened and closed."] = "Las barras ajustadas a un borde de la pantalla o con longitud completa empiezan en su sitio tras iniciar sesión en lugar de necesitar abrir y cerrar el Modo desbloqueo."
L["The cast bar latency zone works for queued spells and remains visible during channels, with configurable color and millisecond text."] = "La zona de latencia de la barra de lanzamiento funciona con hechizos en cola y sigue visible durante las canalizaciones, con color y texto en milisegundos configurables."
L["Class, Power and Health Bars, Cast Bar, GCD Bar, Swing Timer and Totem Bar, each element with its own Unlock Mode mover. Older profiles migrate once."] = "Barras de clase, recurso y vida, Barra de lanzamiento, Barra de TGR, Temporizador de golpe y Barra de tótems, cada elemento con su propio movedor del Modo desbloqueo. Los perfiles antiguos se migran una vez."
L["Main hand, off hand and ranged swings from the combat log, with queued Heroic Strike, Cleave and Maul, parry haste and speed changes."] = "Golpes de mano principal, mano secundaria y a distancia desde el registro de combate, con Golpe heroico, Rajar y Magullar en cola, aceleración por parada y cambios de velocidad."
L["Bar textures include textures from SharedMedia and other addons"] = "Las texturas de barra incluyen texturas de SharedMedia y de otros addons"
L["Vertical bars, Retail texts, gradients, thresholds, tick marks and smoothing"] = "Barras verticales, textos de Retail, degradados, umbrales, marcas y suavizado"
L["Death Knight rune order and countdowns, combo points, or Blizzard's own art"] = "Orden y cuentas atrás de las runas de Caballero de la Muerte, puntos de combo o el arte propio de Blizzard"
L["Channel ticks, latency, total duration and uninterruptible colors"] = "Tics de canalización, latencia, duración total y colores de no interrumpible"
L["Totem icons and timers, and a movable Call Totem Bar"] = "Iconos y temporizadores de tótems, y una Barra de invocación de tótems movible"
L["The Call Totem Bar no longer resizes or moves during combat; changes apply when combat ends."] = "La Barra de invocación de tótems ya no se redimensiona ni se mueve en combate; los cambios se aplican al terminar el combate."
L["The player cast bar shows the channeled spell's name instead of \"Channeling\"."] = "La barra de lanzamiento del jugador muestra el nombre del hechizo canalizado en lugar de \"Canalizando\"."
L["Class icons in the EUI themes, status orbs, notes in the details line, faction banners and hover highlight, with borders and accent colors."] = "Iconos de clase en los temas de EUI, orbes de estado, notas en la línea de detalles, estandartes de facción y resaltado al pasar el ratón, con bordes y colores de acento."
L["Accepts group invites from friends, and optionally from guild members, and closes the popup."] = "Acepta invitaciones de grupo de amigos, y opcionalmente de miembros de la hermandad, y cierra la ventana."
L["The window stays native but rows still get class icons and colored names"] = "La ventana sigue siendo nativa, pero las filas reciben iconos de clase y nombres con color"
L["Auto Accept picks quests from NPC dialogs, with Prevent Multi Quest Accept, and Auto Turn In completes single-reward quests. Hold Shift to skip."] = "Aceptar automáticamente toma misiones de los diálogos de PNJ, con Evitar aceptar varias misiones, y Entregar automáticamente completa misiones de una sola recompensa. Mantén Shift para omitirlo."
L["Uses the item of your tracked quest, found in the quest log, and only holds the key while there is an item to use."] = "Usa el objeto de tu misión seguida, encontrado en el registro de misiones, y solo ocupa la tecla mientras haya un objeto que usar."
L["The top line uses the accent color and Line Color tints the header divider"] = "La línea superior usa el color de acento y Color de línea tiñe el divisor del encabezado"
L["/eqt show, /eqt hide and /eqt toggle"] = "/eqt show, /eqt hide y /eqt toggle"
L["Clear your focus by clicking the focus frame (Shift + Right Click by default, or Ctrl/Alt + Right Click, Middle Click, Shift + Left Click). Set it on the Focus frame page. Works in combat."] = "Quita tu foco haciendo clic en el marco de foco (Shift + Clic derecho por defecto, o Ctrl/Alt + Clic derecho, Clic central, Shift + Clic izquierdo). Configúralo en la página del marco de Foco. Funciona en combate."
L["Two new debuff filter modes: Raid Debuffs shows the common raid debuffs from anyone (armor, spell and physical damage taken, crit taken, attack power, attack and cast speed, healing taken, Judgements and Hunter's Mark), and Own and Raid Debuffs adds yours."] = "Dos nuevos modos de filtro de perjuicios: Perjuicios de banda muestra los perjuicios de banda comunes de cualquiera (armadura, daño de hechizos y físico recibido, críticos recibidos, poder de ataque, velocidad de ataque y lanzamiento, sanación recibida, Sentencias y Marca del cazador), y Perjuicios propios y de banda añade los tuyos."
L["Type Icon Position puts the icon of the player's highest dispellable debuff type on a point of the health bar, with its size and offsets in the cog. Only Dispellable by You now sits beside it and narrows the overlay, icon and border colors alike."] = "Posición del icono de tipo pone el icono del tipo de perjuicio disipable más alto del jugador en un punto de la barra de vida, con su tamaño y desplazamientos en el engranaje. Solo disipables por ti ahora está a su lado y limita por igual la superposición, el icono y los colores del borde."
L["The focus frame gets the aura Border Style, size and color settings, as player and target have."] = "El marco de foco obtiene los ajustes de Estilo del borde, tamaño y color de las auras, como el jugador y el objetivo."
L["Player, target and focus show incoming heals past the health fill: yours and other players' in their own colors, from LibHealComm-4.0 (only healers running a HealComm addon are seen)."] = "Jugador, objetivo y foco muestran las sanaciones entrantes más allá del relleno de vida: las tuyas y las de otros jugadores con sus propios colores, desde LibHealComm-4.0 (solo se ven los sanadores que usan un addon HealComm)."
L["The debuff filters can now show or hide Sated, Exhaustion and the other Bloodlust lockout debuffs. They stay hidden by default."] = "Los filtros de perjuicios ahora pueden mostrar u ocultar Saciado, Agotamiento y los demás perjuicios de bloqueo de Ansia de sangre. Siguen ocultos por defecto."
L["Left, Right, Center and Extra Text, the Bottom Text Bar texts and Power Percent each have an Outline choice under Size: None, Outline, Thick Outline or Shadow, or the module default."] = "Texto izquierdo, derecho, central y extra, los textos de la Barra de texto inferior y Porcentaje de recurso tienen cada uno una opción de Contorno bajo Tamaño: Ninguno, Contorno, Contorno grueso o Sombras, o el predeterminado del módulo."
L["Anchor, growth, icons per row, duration and stack text, textured borders and dispel rings. Target and focus get Purgeable Buff Glow."] = "Anclaje, crecimiento, iconos por fila, texto de duración y acumulaciones, bordes con textura y anillos de disipación. Objetivo y foco obtienen Resplandor de beneficios purgables."
L["Every combat indicator style now shows, and highlighted portraits fit their shape instead of overflowing it."] = "Ahora se muestran todos los estilos de indicador de combate, y los retratos resaltados se ajustan a su forma en lugar de desbordarla."
L["Player, target, focus and boss health bars show estimated damage shields with Retail's Absorb Style, Opacity, Color, Placement, Show Overshield and Show on Boss Frames"] = "Las barras de vida de jugador, objetivo, foco y jefes muestran los escudos de daño estimados con Estilo de absorción, Opacidad, Color, Ubicación, Mostrar sobreescudo y Mostrar en marcos de jefe de Retail"
L["Mana or Mana + Form Power, with a separate form bar"] = "Maná o Maná + poder de forma, con una barra de forma separada"
L["Threat %, a pet power bar and the pet happiness icon"] = "Amenaza %, una barra de recurso de la mascota y el icono de felicidad de la mascota"
L["Pooled aura indicators on the health bar with Use Indicator Layout"] = "Indicadores de aura agrupados en la barra de vida con Usar diseño de indicadores"
L["Fill, full, gradient and sharp gradient overlays in the dispel color"] = "Superposiciones de relleno, completa, degradado y degradado nítido en el color de disipación"
L["Under Classic WoW UI and Blizzard Style, the leader crown sits on the portrait's top corner, as on the original frames, instead of inside the health bar."] = "Con Interfaz de WoW clásico y Estilo Blizzard, la corona de líder queda en la esquina superior del retrato, como en los marcos originales, en lugar de dentro de la barra de vida."
L["The party leader icon on unit frames shows on the leader only instead of on several party members."] = "El icono de líder del grupo en los marcos de unidad se muestra solo en el líder en lugar de en varios miembros del grupo."
L["Set Focus and Clear Focus in the unit frame right-click menu work out of combat without the 'blocked from an action' popup; in combat they are hidden."] = "Establecer foco y Quitar foco en el menú de clic derecho de los marcos de unidad funcionan fuera de combate sin la ventana de 'acción bloqueada'; en combate se ocultan."
L["Unit frame bars and portraits no longer get moved into scroll frames when !!!ClassicAPI is installed."] = "Las barras y retratos de los marcos de unidad ya no se mueven a marcos de desplazamiento cuando !!!ClassicAPI está instalado."
L["Important Cast Glow is hidden for target and focus cast bars; the Wrath client cannot tell which spells are important."] = "Resplandor de lanzamiento importante se oculta en las barras de lanzamiento del objetivo y del foco; el cliente de Wrath no puede saber qué hechizos son importantes."
L["Channel cast bars show the spell's name instead of \"Channeling\"."] = "Las barras de lanzamiento canalizado muestran el nombre del hechizo en lugar de \"Canalizando\"."
L["Boss frames now update health, power and text while the boss is not your target or focus."] = "Los marcos de jefe ahora actualizan la vida, el recurso y el texto mientras el jefe no es tu objetivo ni tu foco."
L["Visibility conditions (combat, group, and hiding without a target) now apply to the frames instead of stopping with an error, so the Visibility menu's boxes also tick right away."] = "Las condiciones de visibilidad (combate, grupo y ocultar sin objetivo) ahora se aplican a los marcos en lugar de detenerse con un error, así que las casillas del menú Visibilidad también se marcan al instante."
L["Classic WoW UI power bars now stay inside the frame art: the art's rim draws over the power bar as it does over the health bar."] = "Las barras de recurso de Interfaz de WoW clásico ahora quedan dentro del arte del marco: el borde del arte se dibuja sobre la barra de recurso igual que sobre la barra de vida."
L["Classic WoW UI now gives every unit frame the original green health bar instead of class colors. Returning to the EllesmereUI look restores your colors."] = "Interfaz de WoW clásico ahora da a todos los marcos de unidad la barra de vida verde original en lugar de los colores de clase. Volver al aspecto EllesmereUI restaura tus colores."
L["Classic WoW UI power bars use the original game colors (deep blue mana, red rage, yellow energy) instead of the EllesmereUI palette. Other looks keep the palette."] = "Las barras de recurso de Interfaz de WoW clásico usan los colores originales del juego (maná azul oscuro, ira roja, energía amarilla) en lugar de la paleta de EllesmereUI. Los demás aspectos mantienen la paleta."
L["Text outlines now apply to the live frames, not only the options preview."] = "Los contornos de texto ahora se aplican a los marcos reales, no solo a la vista previa de las opciones."
L["Unit frames no longer fail to load on setups whose mask textures come back empty (absorb bar error at login)."] = "Los marcos de unidad ya no fallan al cargar en configuraciones cuyas texturas de máscara vuelven vacías (error de la barra de absorción al iniciar sesión)."
L["Icons shown by spell ID now show the right icon or a question mark, never an empty square."] = "Los iconos mostrados por ID de hechizo ahora muestran el icono correcto o un signo de interrogación, nunca un cuadrado vacío."
L["The faction indicator no longer errors in mercenary mode, and Retail-only PvP styles use the Wrath PvP icon."] = "El indicador de facción ya no da error en modo mercenario, y los estilos de JcJ exclusivos de Retail usan el icono JcJ de Wrath."
L["Level text no longer errors with Font not set when frames are first created."] = "El texto de nivel ya no da el error Font not set cuando se crean los marcos por primera vez."
L["Like Retail 9.4, the Experience Bar section opens with XP Bar Style: EllesmereUI for the EUI bar, Luxthos for the EUI bar in the Luxthos WeakAura layout, or Blizz Default for Blizzard's own XP and reputation bars. It replaces Enable Experience Bar and the Apply Luxthos Layout button."] = "Como en Retail 9.4, la sección Barra de experiencia se abre con Estilo de barra de PX: EllesmereUI para la barra de EUI, Luxthos para la barra de EUI con el diseño de la WeakAura de Luxthos, o Predeterminado de Blizz para las barras de PX y reputación propias de Blizzard. Sustituye a Activar barra de experiencia y al botón Aplicar diseño Luxthos."
L["Like Retail 9.4, any horizontal bar can show the classic gryphons at its left end, right end or both, from the End Caps menu at the end of LAYOUT. The cog sets their size and offsets, and Apply to All copies them to every bar. The live preview shows them too."] = "Como en Retail 9.4, cualquier barra horizontal puede mostrar los grifos clásicos en su extremo izquierdo, derecho o en ambos, desde el menú Remates al final de DISEÑO. El engranaje ajusta su tamaño y desplazamientos, y Aplicar a todo los copia a todas las barras. La vista previa en vivo también los muestra."
L["The XP bar gets Retail's Quest XP Overlay (completed quests in green, incomplete in gold), dividers with Smart Ticks, gradient fills, background and rested colors, and seven text positions showing values, completed quest XP, XP per hour, time to level and time played. Apply Luxthos Layout recreates the popular Luxthos XP bar WeakAura, with Show at Max Level, a spark and rested XP after quest XP."] = "La barra de PX obtiene la Superposición de PX de misiones de Retail (misiones completadas en verde, incompletas en dorado), divisores con Marcas inteligentes, rellenos con degradado, colores de fondo y de descanso, y siete posiciones de texto que muestran valores, PX de misiones completadas, PX por hora, tiempo hasta subir de nivel y tiempo jugado. Aplicar diseño Luxthos recrea la popular WeakAura de barra de PX de Luxthos, con Mostrar al nivel máximo, una chispa y PX de descanso tras la PX de misiones."
L["Buttons holding an equipped item, such as a trinket, can show a border in its rarity color. Off by default."] = "Los botones que contienen un objeto equipado, como un abalorio, pueden mostrar un borde del color de su rareza. Desactivado por defecto."
L["Four extra bars, off by default, each with its own keybinds, Unlock Mode mover and the full Bar Display settings. Warriors, Druids, Rogues and Priests see which stance or form shares a bar's slots."] = "Cuatro barras extra, desactivadas por defecto, cada una con sus propios atajos, movedor del Modo desbloqueo y todos los ajustes de Visualización de barra. Guerreros, druidas, pícaros y sacerdotes ven qué actitud o forma comparte las casillas de una barra."
L["Circle and Portrait draw round icons, Diamond, Hexagon and Shield crop the icon to the shape, and Square and Curved Square add a shaped outline. Set per bar, including pet and stance."] = "Círculo y Retrato dibujan iconos redondos, Rombo, Hexágono y Escudo recortan el icono con la forma, y Cuadrado y Cuadrado curvado añaden un contorno con forma. Se ajusta por barra, incluidas la de mascota y la de actitud."
L["Type /kb, hover a button and press a key to bind it, including modifiers, mouse buttons and the wheel. Right-click clears; Cancel or Esc undoes."] = "Escribe /kb, pasa el ratón sobre un botón y pulsa una tecla para asignarla, incluidos modificadores, botones del ratón y la rueda. Clic derecho la borra; Cancelar o Esc deshace."
L["Per-bar text, borders, backgrounds, orientation and growth, the Retail button animations and visibility engine, and Bar 1 modifier paging."] = "Texto, bordes, fondos, orientación y crecimiento por barra, las animaciones de botones y el motor de visibilidad de Retail, y el cambio de página con modificadores de la Barra 1."
L["Shift+1 shows as S1, Control+1 as C1, mouse buttons as M4 and the wheel as MwU/MwD"] = "Shift+1 se muestra como S1, Control+1 como C1, los botones del ratón como M4 y la rueda como MwU/MwD"
L["Shrink the bag bar to a single backpack button"] = "Reduce la barra de bolsas a un único botón de mochila"
L["Square micro menu and bag bar, flat XP and reputation bars and movable buffs and debuffs"] = "Micromenú y barra de bolsas cuadrados, barras de PX y reputación planas y beneficios y perjuicios movibles"
L["Bar 1 paging arrows change the page without the \"blocked from an action only available to the Blizzard UI\" message."] = "Las flechas de página de la Barra 1 cambian la página sin el mensaje \"blocked from an action only available to the Blizzard UI\"."
L["Changing stance no longer reveals a duplicate Blizzard stance and pet bar."] = "Cambiar de actitud ya no revela una barra de actitud y de mascota de Blizzard duplicada."
L["Spells can be dropped on Bar 1 while the Blizzard bar art is hidden."] = "Se pueden soltar hechizos en la Barra 1 mientras el arte de la barra de Blizzard está oculto."
L["Player Buffs keep growing downward as rows are added."] = "Los beneficios del jugador siguen creciendo hacia abajo a medida que se añaden filas."
L["The XP and reputation bars no longer error on their first update."] = "Las barras de PX y reputación ya no dan error en su primera actualización."
L["Create Soulstone reminders, including custom spell reminders, only appear for Warlocks."] = "Los recordatorios de Crear piedra de alma, incluidos los recordatorios de hechizos personalizados, solo aparecen para brujos."
L["A Holy-only reminder for your Seal of Wisdom, including when another seal is active."] = "Un recordatorio solo para Sagrado de tu Sello de sabiduría, también cuando hay otro sello activo."
L["One click casts your group buff, such as Fortitude, Gift of the Wild or Arcane Brilliance, at its highest rank on the first member missing it."] = "Un clic lanza el beneficio de tu grupo, como Entereza, Don de lo Salvaje o Luminosidad Arcana, con su rango más alto sobre el primer miembro al que le falte."
L["Auras, presences, aspects, shields, weapon imbues, poisons, pets, Soulstone and Healthstone, plus flask, elixir and food with bag counts."] = "Auras, presencias, aspectos, escudos, mejoras de arma, venenos, mascotas, Piedra de alma y Piedra de salud, además de frasco, elixir y comida con recuento en las bolsas."
L["Reminder sounds include SharedMedia sounds, even from packs that load later"] = "Los sonidos de los recordatorios incluyen sonidos de SharedMedia, incluso de paquetes que se cargan más tarde"
L["World, normal and heroic dungeons and raids, or in combat, with Show Below timers"] = "Mundo, mazmorras y bandas normales y heroicas, o en combate, con temporizadores de Mostrar debajo"
L["Talent reminders for Wrath zones and your current instance"] = "Recordatorios de talentos para las zonas de Wrath y tu estancia actual"
L["Your own aura ID reminders and a healer mana Ready Check Warning"] = "Tus propios recordatorios por ID de aura y un aviso de maná de sanador en la comprobación de disponibilidad"
L["Middle-click hides a reminder until the next loading screen"] = "Clic central oculta un recordatorio hasta la siguiente pantalla de carga"
L["Turning off Runeforging now hides the Death Knight rune reminder."] = "Desactivar Forja de runas ahora oculta el recordatorio de runa de Caballero de la Muerte."
L["Adding zones to an older talent reminder no longer errors, and the new zones apply right away."] = "Añadir zonas a un recordatorio de talento antiguo ya no da error, y las nuevas zonas se aplican al instante."
L["A coin in the bag header marks items as junk: click it, then click items. Grey and marked items go to a Junk category, and a Sell Junk button appears next to the coin at merchants. Its cog adds a coin badge on marked items."] = "Una moneda en el encabezado de las bolsas marca objetos como basura: haz clic en ella y luego en los objetos. Los objetos grises y marcados van a una categoría Basura, y aparece un botón Vender basura junto a la moneda en los vendedores. Su engranaje añade una insignia de moneda en los objetos marcados."
L["Bag keybinds open and close the existing layout during combat. Layout refreshes wait until combat ends."] = "Los atajos de bolsas abren y cierran el diseño existente durante el combate. Las actualizaciones del diseño esperan al final del combate."
L["A sidebar with All Items, OneBag and MultiBag views, pinned and recent items, Retail categories for Wrath items and your own categories."] = "Una barra lateral con las vistas Todos los objetos, OneBag y MultiBag, objetos fijados y recientes, categorías de Retail para objetos de Wrath y tus propias categorías."
L["OneBag merges stacks and sorts by bag type, MultiBag sorts each bag, with Sort to Bottom and Randomize."] = "OneBag combina montones y ordena por tipo de bolsa, MultiBag ordena cada bolsa, con Ordenar al final y Aleatorizar."
L["A cog beside the search opens the Bags options, or the Bank page at the bank"] = "Un engranaje junto a la búsqueda abre las opciones de Bolsas, o la página Banco en el banco"
L["Each saved character in the Characters list has an x to delete its data"] = "Cada personaje guardado de la lista Personajes tiene una x para borrar sus datos"
L["Quality borders, quest marks, item level, BoE text, set names and dimmed junk"] = "Bordes de calidad, marcas de misión, nivel de objeto, texto de BoE, nombres de conjunto y basura atenuada"
L["Group the bank by category, with a sidebar"] = "Agrupa el banco por categoría, con una barra lateral"
L["With Enable Bags off, the default bag functions are no longer replaced, avoiding blocked action errors from tainted bag code."] = "Con Activar bolsas desactivado, las funciones de bolsa predeterminadas ya no se sustituyen, lo que evita errores de acción bloqueada por código de bolsas contaminado."
L["Opening the Characters list no longer errors."] = "Abrir la lista Personajes ya no da error."
L["Gold sale ads with websites or cash prices, including 5000G=20 bucks and disguised W.W.W addresses, are filtered by default in your selected chat scopes."] = "Los anuncios de venta de oro con sitios web o precios en dinero, incluidos 5000G=20 bucks y direcciones W.W.W disfrazadas, se filtran por defecto en los ámbitos de chat seleccionados."
L["Unsupported server channel notices such as NOT_IN_LFG no longer cause the native chat formatter to error."] = "Los avisos de canal del servidor no admitidos, como NOT_IN_LFG, ya no provocan errores en el formateador de chat nativo."
L["Optional spam filtering with a repeat window, sender matching and public, group or whisper controls."] = "Filtrado de spam opcional con una ventana de repetición, coincidencia de remitente y controles para chat público, de grupo o susurros."
L["Background, divider, input position, Retail border and tabs over the native dock, plus a sidebar with friends, guild, copy, channels and settings."] = "Fondo, divisor, posición del cuadro de entrada, borde y pestañas de Retail sobre el acoplamiento nativo, además de una barra lateral con amigos, hermandad, copiar, canales y ajustes."
L["Retail timestamps, short channel names, class colored names, link tooltips, whisper sounds, saved chat history and Retail URL and copy windows."] = "Marcas de hora de Retail, nombres de canal cortos, nombres con color de clase, descripciones de enlaces, sonidos de susurro, historial de chat guardado y ventanas de URL y copia de Retail."
L["Show Hidden Messages lists the last 200 lines the spam filter hid this session, with time, reason, channel and sender. Clear Filter History is now Reset Repeat Memory."] = "Mostrar mensajes ocultos muestra las últimas 200 líneas que el filtro de spam ocultó en esta sesión, con hora, motivo, canal y remitente. Borrar historial del filtro ahora es Restablecer memoria de repeticiones."
L["The trade ad preset also hides LFW (looking for work) crafting ads."] = "El preajuste de anuncios de comercio también oculta los anuncios de artesanía LFW (busco trabajo)."
L["Right-click the chat in Unlock Mode to open its Display settings"] = "Haz clic derecho en el chat en el Modo desbloqueo para abrir sus ajustes de Visualización"
L["Restyled chat bubbles with per-channel toggles and hiding in instances"] = "Bocadillos de chat rediseñados con interruptores por canal y ocultación en estancias"
L["The chat fades after a delay and comes back on mouseover"] = "El chat se desvanece tras un retraso y vuelve al pasar el ratón"
L["Copy Chat copies the chat tab you are looking at instead of the last tab you right-clicked, which could show \"(No chat history)\"."] = "Copiar chat copia la pestaña de chat que estás viendo en lugar de la última pestaña en la que hiciste clic derecho, que podía mostrar \"(No chat history)\"."
L["Fixed a \"SetPoint(): is dependent on this\" error when styling some NPC chat bubbles."] = "Corregido un error \"SetPoint(): is dependent on this\" al dar estilo a algunos bocadillos de chat de PNJ."
L["The guild recruitment filter no longer hides raid ads that mention a guild, such as \"<Frost> LF 1 heal ICC25\"; only LF guild phrases count."] = "El filtro de reclutamiento de hermandad ya no oculta anuncios de banda que mencionan una hermandad, como \"<Frost> LF 1 heal ICC25\"; solo cuentan las frases de búsqueda de hermandad."
L["GM whispers and messages are never hidden by the spam filter."] = "Los susurros y mensajes de MJ nunca se ocultan con el filtro de spam."
L["Spam filter keywords ignore case for accented letters too, so promoção also hides PROMOÇÃO."] = "Las palabras clave del filtro de spam ignoran mayúsculas y minúsculas también en letras acentuadas, así que promoção también oculta PROMOÇÃO."
L["The trade ad and guild recruitment filters follow the Public Chat setting, and the spam filter does no work while every filter is off."] = "Los filtros de anuncios de comercio y de reclutamiento de hermandad siguen el ajuste Chat público, y el filtro de spam no trabaja mientras todos los filtros estén desactivados."
L["The sidebar shows on first load, and tabs and toggles update right away."] = "La barra lateral se muestra en la primera carga, y las pestañas e interruptores se actualizan al instante."
L["The main chat keeps its Unlock Mode position instead of being reset by the dock."] = "El chat principal mantiene su posición del Modo desbloqueo en lugar de que el acoplamiento la restablezca."
L["A saved chat opacity of 0 resets once to the Retail default."] = "Una opacidad de chat guardada de 0 se restablece una vez al valor predeterminado de Retail."
L["Square, rectangular, circle and textured circle maps, with border size, opacity, textured styles and custom, accent or class colors."] = "Mapas cuadrados, rectangulares, circulares y circulares con textura, con tamaño de borde, opacidad, estilos con textura y colores personalizados, de acento o de clase."
L["Addon buttons collect into the Retail flyout with a grid, grow direction and Shift-drag Free Move."] = "Los botones de addons se reúnen en el menú desplegable de Retail con cuadrícula, dirección de crecimiento y Movimiento libre con Shift + arrastrar."
L["A vanilla ring and zone banner with native zoom buttons"] = "Un anillo vanilla y un letrero de zona con botones de zoom nativos"
L["Clock and zone boxes in ten positions, plus coordinates, FPS and latency, and difficulty text"] = "Cuadros de reloj y zona en diez posiciones, además de coordenadas, FPS y latencia, y texto de dificultad"
L["Guild and friends at a glance; left-click whispers, right-click invites"] = "Hermandad y amigos de un vistazo; clic izquierdo susurra, clic derecho invita"
L["Menu actions open Blizzard windows through secure calls, avoiding blocked action errors."] = "Las acciones del menú abren ventanas de Blizzard mediante llamadas seguras, evitando errores de acción bloqueada."
L["Pick Classic WoW UI for Damage Meters on the Style page: each window gets the classic tooltip border, a tooltip header band and vanilla header icons, and keeps every EllesmereUI meter feature."] = "Elige Interfaz de WoW clásico para el Medidor de daño en la página Estilo: cada ventana recibe el borde clásico de descripción, una franja de encabezado de descripción e iconos de encabezado vanilla, y conserva todas las funciones del medidor de EllesmereUI."
L["A spell's breakdown tooltip shows its Spell ID, and each spell row in the detailed window ends with its ID."] = "La descripción del desglose de un hechizo muestra su ID de hechizo, y cada fila de hechizo de la ventana detallada termina con su ID."
L["Consumed shield absorbs count toward Healing Done and HPS when the caster can be identified, with an Absorbs Done view."] = "Las absorciones de escudos consumidas cuentan para Sanación realizada y SPS cuando se puede identificar al lanzador, con una vista de Absorciones realizadas."
L["Flat body, accent header, Atrocity bars and header icons for Settings, Segment, Meter Type and Reset, with up to five windows."] = "Cuerpo plano, encabezado de acento, barras Atrocity e iconos de encabezado para Ajustes, Segmento, Tipo de medidor y Restablecer, con hasta cinco ventanas."
L["Up to 15 spells and the top three targets on hover, death recaps with health at each hit, and a per-player focus view."] = "Hasta 15 hechizos y los tres objetivos principales al pasar el ratón, resúmenes de muerte con la vida en cada golpe y una vista de foco por jugador."
L["SharedMedia bar textures load whether a profile stores them in Damage Meters or EllesmereUI format"] = "Las texturas de barra de SharedMedia se cargan tanto si un perfil las guarda en formato de Medidor de daño como de EllesmereUI"
L["An icon strip and bar window of your casts, including failed and interrupted ones"] = "Una franja de iconos y una ventana de barras con tus lanzamientos, incluidos los fallidos e interrumpidos"
L["A standalone combat timer with its own Unlock Mode element"] = "Un temporizador de combate independiente con su propio elemento del Modo desbloqueo"
L["Windows snap to each other; locked windows cannot move, resize or close"] = "Las ventanas se ajustan entre sí; las ventanas bloqueadas no se pueden mover, redimensionar ni cerrar"
L["Keybinds for Reset Data and Show / Hide Windows"] = "Atajos para Restablecer datos y Mostrar / ocultar ventanas"
L["Specialization icons from talent data and paced group inspection"] = "Iconos de especialización a partir de los datos de talentos e inspección del grupo pausada"
L["Load an action menu only in your primary or secondary talent group, and let two menus share one keybind across specs."] = "Carga un menú de acciones solo en tu grupo de talentos principal o secundario, y deja que dos menús compartan un atajo entre especializaciones."
L["Hold a key, point or scroll to choose, release to fire. Up to 16 palettes of 20 entries in ring, arc, fan or grid layouts."] = "Mantén una tecla, apunta o desplaza para elegir y suelta para activar. Hasta 16 paletas de 20 entradas en diseños de anillo, arco, abanico o cuadrícula."
L["An Action Menu entry fans out up to 8 actions from another palette, one level out from the ring."] = "Una entrada de Menú de acciones despliega hasta 8 acciones de otra paleta, un nivel hacia fuera del anillo."
L["Accent, class or custom color for the selected entry, needle and nested highlight"] = "Color de acento, de clase o personalizado para la entrada seleccionada, la aguja y el resaltado anidado"
L["Set the gap between a nested menu and its entry, and the nested icon size"] = "Ajusta la separación entre un menú anidado y su entrada, y el tamaño de los iconos anidados"
L["Reverse which way a wheel tick moves the selection"] = "Invierte el sentido en que un paso de la rueda mueve la selección"
L["Assign Key captures the next key with modifiers and asks before rebinding"] = "Asignar tecla captura la siguiente tecla con modificadores y pregunta antes de reasignar"
L["Keep the menu open on release and fire with a Select key"] = "Mantén el menú abierto al soltar y activa con una tecla Seleccionar"
L["Red when out of range, blue when short of power, grey when unusable"] = "Rojo fuera de alcance, azul con recurso insuficiente, gris cuando no se puede usar"
